-- Conteúdo real de Nefrologia: aulas 1 e 2, banco de questões das provas P2 e flashcards

update public.aulas set publicada = false where id in ('lra', 'potassio');  -- esconde os exemplos do protótipo
update public.materias set descricao = 'Patologias renais com a Dra. Vanessa: definições, doenças císticas e o banco de questões das provas P2.' where id = 'nefro';

insert into public.aulas (id, materia_id, ordem, titulo, resumo, apostila_html, pdf_caminho) values
  ('nefro-a1', 'nefro', 1, 'Definições e produtos do metabolismo', 'Volume urinário, como avaliar o rim, ureia, ácido úrico, creatina e creatinina.',
$ap$<div class="legenda"><span class="lg"><i class="sw blue"></i>Conteúdo da aula</span><span class="lg"><i class="sw green"></i>Valor normal</span><span class="lg"><i class="sw red"></i>Alerta ou erro comum</span><span class="lg"><i class="sw orange"></i>Fala da professora</span><span class="lg"><i class="sw purple"></i>Complemento fora da aula</span><span class="lg"><span class="prova">PROVA</span>Cai na prova</span></div><div class="tiles"><div class="tile g"><div class="lab">Diurese normal</div><div class="n">2.100 a 2.800 mL</div><div class="s">de urina em 24 horas</div></div><div class="tile g"><div class="lab">Ureia</div><div class="n">10 a 40 mg/dL</div><div class="s">no sangue</div></div><div class="tile g"><div class="lab">Creatinina</div><div class="n">&lt; 1,2 mg/dL</div><div class="s">no sangue; ideal abaixo de 1,0</div></div></div><h3 class="sec-h"><span class="sn">00</span>Recados da disciplina</h3><p>A Dra. Vanessa vai dar as próximas 8 aulas teóricas, sobre as patologias renais. Esta primeira é curta, mas é a base de tudo o que vem depois.</p><div class="date"><div class="d"><span class="m">Novembro</span><span class="dd">12</span></div><div class="t"><b>Prova de Nefrologia da Dra. Vanessa</b><span>Quinta-feira, às 10h30, no horário da turma. A data foi marcada com dois meses e meio de antecedência e não será mudada.</span></div></div><div class="linhas"><div class="ln"><div class="k">Nota</div><div class="v">A prova do Dr. Guilherme vale 9. A prova da Dra. Vanessa vale 9. Os 2 pontos restantes vêm das aulas práticas (Dr. Guilherme, Dra. Vanessa e Dra. Ana Andressa: frequência e participação) e do seminário.</div></div><div class="ln"><div class="k">Presença</div><div class="v">Lista de presença que passa pela sala. Assine só o seu nome, nunca o de um colega: no fim do semestre a professora compara todas as assinaturas.</div></div><div class="ln"><div class="k">Na prova</div><div class="v">As provas são objetivas: escreva o seu nome. No semestre passado houve provas sem nome, e não há como saber de quem são.</div></div><div class="ln"><div class="k">Perguntas</div><div class="v">Pergunte durante a aula, não no final. A dúvida de um costuma ser a de muitos. O que a professora não souber, ela estuda e responde na aula seguinte.</div></div><div class="ln"><div class="k">Slides</div><div class="v">Vão para o representante de turma, em geral 3 a 4 dias depois da aula. Parecem antigos, mas são revisados na semana de cada aula.</div></div><div class="ln"><div class="k">Gravação</div><div class="v">Pode gravar, desde que avise a professora no começo da aula.</div></div><div class="ln"><div class="k">Celular</div><div class="v">Só atender se for pai, mãe ou filho. O resto fica para depois da aula.</div></div></div><div class="box"><div class="kick"><span class="dot"></span>O que ela cobra e o que não cobra</div><p>Ela não vai cobrar reações bioquímicas nem fórmulas químicas. Ela vai cobrar que você entenda de onde vêm a ureia, o ácido úrico e a creatinina, e o que significa quando eles sobem.</p></div><div class="quote"><p>“Vocês não terão que estudar no dia anterior, terão que estudar todos os dias.”</p><div class="who">Dra. Vanessa, sobre a semana com três provas</div></div><h3 class="sec-h"><span class="sn">01</span>Volume urinário</h3><p><b>Diurese</b> é o volume de urina que a pessoa produz em 24 horas. Os valores abaixo valem para um adulto de 70 kg e dependem de quanto líquido ele bebe.</p><h4>As faixas de diurese <span class="prova">PROVA</span></h4><div class="faixas"><div class="fx r"><b>Anúria</b><span class="v">0 mL</span><span>A pessoa não urina.</span></div><div class="fx r"><b>Oligúria</b><span class="v">&lt; 400 mL</span><span>Urina pouco.</span></div><div class="fx n"><b>Sem nome</b><span class="v">400 a 2.100 mL</span><span>Faixa sem nome na aula.</span></div><div class="fx g"><b>Normal</b><span class="v">2.100 a 2.800 mL</span><span>Cerca de 30 a 40 mL por quilo.</span></div><div class="fx r"><b>Poliúria</b><span class="v">&gt; 3.000 mL</span><span>Urina demais.</span></div></div><p class="nota">Todos os volumes são em 24 horas.</p><div class="box"><div class="kick"><span class="dot"></span>Guarde para a aula de doença renal crônica</div><p>Os pacientes da diálise vivem em anúria (não urinam nada) ou em oligúria (urinam muito pouco). Quem teve prática com a Dra. Vanessa já viu isso na clínica de diálise.</p></div><div class="box purple"><div class="kick"><span class="dot"></span>Complemento: fora da aula</div><p>Muitos livros definem anúria como diurese abaixo de 50 a 100 mL em 24 horas, e não como zero absoluto. Na prova da Dra. Vanessa, use a definição dela: ausência de diurese.</p></div><h3 class="sec-h"><span class="sn">02</span>Como avaliar a função do rim</h3><p>Com o Dr. Guilherme vocês viram como o rim controla a água, o sódio, o ácido úrico e os ácidos, e o que cada parte do néfron absorve. Na prática clínica, a pergunta é outra, e cada parte tem os seus exames.</p><h4>A lesão do paciente está no glomérulo ou no túbulo? <span class="prova">PROVA</span></h4><div class="grid"><div class="card"><span class="tag">Glomérulo: o filtro</span><p>Mostram se o rim está filtrando.</p><ul><li>Ureia no sangue</li><li>Creatinina no sangue</li><li>Depuração de creatinina (o “clearance”), que é a taxa de filtração glomerular</li><li>Proteína na urina, que o glomérulo saudável não deixa passar</li></ul></div><div class="card"><span class="tag">Túbulos: o ajuste fino</span><p>Mostram se o rim sabe concentrar a urina e ajustar os sais.</p><ul><li>Exame de urina simples</li><li>Densidade urinária: o quanto a urina está concentrada</li><li>Osmolaridade urinária: a quantidade de partículas dissolvidas na urina</li><li>Sódio e potássio urinários</li></ul></div></div><h3 class="sec-h"><span class="sn">03</span>Ureia: da proteína à urina</h3><p>A ureia é um produto do metabolismo das proteínas. Ela existe para tirar a amônia, que é tóxica, do sangue, numa forma que o rim consegue eliminar.</p><h4>O caminho da ureia <span class="prova">PROVA</span></h4><ol class="flow"><li><b>Proteínas da dieta e do corpo.</b> São quebradas, inclusive pelas bactérias do intestino.</li><li><b>Amônia e gás carbônico.</b> A amônia é extremamente tóxica para todos os tecidos. É a base do sal amoníaco, usado como produto de limpeza.</li><li><b>Transporte até o fígado.</b> Nas células, a amônia é presa em glutamato e glutamina. Nos músculos, ela sai na forma de alanina.</li><li><b>Fígado: ciclo da ureia.</b> Uma sequência de reações transforma a amônia em ureia. Acontece principalmente nas células do fígado e, em menor parte, nas do rim.</li><li><b>Rim: eliminação.</b> A ureia é filtrada e sai na urina.</li></ol><div class="card wide"><span class="tag">De onde vem a amônia</span><ul class="cols2"><li>Quebra (catabolismo) das proteínas</li><li>Dieta rica em proteínas</li><li>Excesso de desaminação: retirada da parte com nitrogênio dos aminoácidos</li><li>Jejum prolongado</li><li>Produção normal pelas bactérias do intestino</li></ul></div><div class="ref"><div class="txt"><div class="kick"><span class="dot"></span>Valor normal · ureia</div><p>Ureia no sangue do adulto.</p></div><div class="val">10 a 40 mg/dL</div></div><div class="box orange"><div class="kick"><span class="dot"></span>Parêntese da professora: e o jejum prolongado?</div><p>Ainda não há como bater o martelo se faz bem ou mal: as pesquisas têm muitos vieses. Uma coisa já se sabe: ele causa halitose (mau hálito). O corpo passa a queimar gordura e elimina parte do que sobra dessa queima pela respiração.</p></div><h4>Dieta pobre em proteína é boa para o rim?</h4><p>Pergunta de um aluno em sala. A resposta: quem come pouca proteína de fato produz pouca ureia. Mas isso não é bom, porque a proteína não serve só para gerar ureia. Ela sustenta a imunidade, cicatriza feridas e ajuda a evitar infecções. A ingestão de proteína não pode ser nem demais nem de menos.</p><div class="quote"><p>“Quem come pouca proteína gera pouca ureia. Isso é bom? Não.”</p><div class="who">Dra. Vanessa</div></div><h4>Quando o rim não funciona</h4><p>Diabetes grave, hipertensão grave e glomerulopatias (doenças do glomérulo) podem destruir o rim. Sem rim, a ureia não é eliminada e se acumula. É esse acúmulo que dá os sintomas da síndrome urêmica, que aparece tanto na doença renal aguda quanto na crônica.</p><div class="es"><div class="kick">Entrada × saída · ureia alta <span class="prova">PROVA</span></div><p class="lead">Paciente com ureia alta na unidade de pronto atendimento ou na unidade básica de saúde. Raciocínio para a prova e para o plantão:</p><div class="cells"><div class="cell"><div class="lab">Entrada</div><p>Está comendo muita proteína.</p></div><div class="cell"><div class="lab">Saída</div><p>Está eliminando pouco pelo rim.</p></div><div class="cell"><div class="lab">Ou as duas</div><p>Na pior das hipóteses, as duas coisas ao mesmo tempo.</p></div></div></div><div class="quote"><p>“Ninguém vai ficar decorando fórmula, é só para vocês entenderem de onde ela vem.”</p><div class="who">Dra. Vanessa, sobre o ciclo da ureia</div></div><h3 class="sec-h"><span class="sn">04</span>Ácido úrico</h3><p>O ácido úrico vem logo depois da ureia porque também está ligado aos alimentos ricos em proteína. Mas ele nasce por outro caminho, a via das xantinas, com outras enzimas do fígado.</p><h4>De onde vem e por onde sai <span class="prova">PROVA</span></h4><div class="grid"><div class="card"><span class="tag">Origem</span><ul><li>Vem da dieta</li><li>É fabricado no fígado, com enzimas diferentes das que fazem a ureia</li></ul></div><div class="card"><span class="tag">Eliminação</span><ul><li>3/4 pelo rim e 1/4 pelo intestino</li><li>90% é reabsorvido no túbulo proximal. Só 10% do que é filtrado sai na urina</li></ul></div></div><h4>O que faz o ácido úrico subir (hiperuricemia)</h4><ul class="cols2"><li>Álcool, inclusive a cerveja.</li><li>Carnes e frutos do mar, quando consumidos em excesso.</li><li>Síndrome de lise tumoral: destruição rápida do tumor depois da quimioterapia.</li><li>Insuficiência renal: o rim deixa de eliminar.</li></ul><div class="es"><div class="kick">Entrada × saída · ureia e ácido úrico altos <span class="prova">PROVA</span></div><p class="lead">O rim é o filtro dos produtos do metabolismo das proteínas. Por isso o paciente com doença renal tende a ter ureia e ácido úrico altos. Se os dois estão altos, pense em:</p><div class="cells"><div class="cell"><div class="lab">Entrada</div><p>Excesso de ganho: muita proteína.</p></div><div class="cell"><div class="lab">Saída</div><p>Menor eliminação pelo rim.</p></div><div class="cell"><div class="lab">Ou as duas</div><p>As duas coisas ao mesmo tempo.</p></div></div></div><div class="box purple"><div class="kick"><span class="dot"></span>Complemento: fora da aula</div><p>Para ser exato, o ácido úrico é o produto final da quebra das purinas, que fazem parte do material genético das células. No caminho, as purinas viram hipoxantina e depois xantina, por isso “via das xantinas”. Carnes, vísceras e frutos do mar são ricos em purinas, e é daí que vem a associação com alimentos proteicos. Na lise tumoral, a morte de muitas células de uma vez libera muitas purinas.</p></div><h4>Ureia e ácido úrico lado a lado</h4><div class="cmp-wrap"><table class="cmp"><thead><tr><th></th><th>Ureia</th><th>Ácido úrico</th></tr></thead><tbody><tr><td>De onde vem</td><td>Proteínas da dieta e do corpo, passando pela amônia</td><td>Da dieta e da produção no fígado</td></tr><tr><td>Onde é feito</td><td>Fígado, no ciclo da ureia (e um pouco no rim)</td><td>Fígado, na via das xantinas</td></tr><tr><td>Valor normal</td><td class="g">10 a 40 mg/dL</td><td class="muted">Não foi dado em aula</td></tr><tr><td>No rim</td><td>É filtrada e sai na urina</td><td>90% é reabsorvido no túbulo proximal; só 10% sai na urina</td></tr><tr><td>Eliminação</td><td>Rim</td><td>3/4 pelo rim, 1/4 pelo intestino</td></tr><tr><td>Sobe com</td><td>Muita proteína, quebra de proteínas, jejum prolongado, rim que não elimina</td><td>Álcool, carnes e frutos do mar, lise tumoral, insuficiência renal</td></tr></tbody></table></div><div class="ref purple"><div class="txt"><div class="kick"><span class="dot"></span>Complemento · ácido úrico</div><p>Valor usual de referência no sangue. Não foi dado em aula e muda de um laboratório para outro.</p></div><div class="vals"><div class="val"><small>Homem</small>3,4 a 7,0 mg/dL</div><div class="val"><small>Mulher</small>2,4 a 6,0 mg/dL</div></div></div><h3 class="sec-h"><span class="sn">05</span>Creatina e creatinina</h3><div class="grid"><div class="card"><span class="tag">Creatina</span><p>Molécula fabricada a partir de três aminoácidos. O músculo a usa como reserva de energia rápida.</p></div><div class="card"><span class="tag">Creatinina</span><p>O resto da creatina e da fosfocreatina do músculo, que o rim elimina. Não é tóxica, mas é marcadora da função do rim.</p></div></div><h4>Por que a creatinina é uma boa marcadora do rim <span class="prova">PROVA</span></h4><ul><li><b>Vem do músculo esquelético.</b> O músculo liso produz pouca ou nenhuma.</li><li><b>A produção é constante</b> e quase não depende do metabolismo do músculo nem da quebra de proteínas. Queira ou não, o músculo queima creatina o tempo todo.</li><li><b>Livremente filtrada,</b> não é reabsorvida e é pouco secretada pelo túbulo.</li></ul><p>Por isso ela é “fiel à função renal”: o que o glomérulo filtra é praticamente o que sai.</p><div class="ref"><div class="txt"><div class="kick"><span class="dot"></span>Valor normal · creatinina</div><p>No adulto. A referência muda um pouco de um laboratório para outro.</p></div><div class="vals"><div class="val"><small>Laboratórios</small>0,8 a 1,3 mg/dL</div><div class="val"><small>Na visão da professora</small>&lt; 1,2 · ideal &lt; 1,0</div></div></div><div class="es"><div class="kick">Entrada × saída · creatinina alta <span class="prova">PROVA</span></div><p class="lead">A creatina, depois de usada, vira creatinina para ser eliminada. Se a creatinina está alta:</p><div class="cells"><div class="cell"><div class="lab">Entrada</div><p>A oferta está alta demais, por ingestão em excesso sem necessidade. O músculo só guarda uma parte, e o excesso “jogado fora” vira creatinina.</p></div><div class="cell"><div class="lab">Saída · a causa principal</div><p>O rim não está filtrando o necessário, e ela sobra no sangue.</p></div></div><p class="foot">Por isso a creatinina no sangue serve tanto para avaliar a função do rim quanto para ajudar a decidir se a pessoa precisa ou não suplementar creatina.</p></div><h4>Como o corpo fabrica creatina, todo dia</h4><ol class="flow"><li><b>Rim: arginina + glicina.</b> A enzima arginina-glicina amidinotransferase passa o grupo com nitrogênio da arginina para a glicina. Saem o ácido guanidinoacético e a ornitina.</li><li><b>Pelo sangue até o fígado.</b> O ácido guanidinoacético sai da circulação do rim e vai para o fígado.</li><li><b>Fígado: + metionina = creatina.</b> Nova reação com um terceiro aminoácido, a metionina. Arginina + glicina + metionina formam a creatina.</li><li><b>Músculo: o grande estoque.</b> O músculo capta a creatina e a guarda como fosfocreatina. Sistema nervoso central, coração e osso também usam.</li><li><b>Creatinina → rim → urina.</b> Creatina e fosfocreatina se quebram em creatinina, que é filtrada e eliminada.</li></ol><div class="grid"><div class="card"><span class="tag">Quanto produzimos</span><div class="big">≈ 1 g por dia</div><p>Sem esforço nenhum, só por existir. Essa quantidade não basta para um efeito ergogênico (melhorar o desempenho físico) ou terapêutico.</p></div><div class="card"><span class="tag">Para que ela serve</span><p>É uma carregadora de fosfato. A fosfocreatina doa fosfato para refazer o trifosfato de adenosina a partir do difosfato de adenosina. O trifosfato de adenosina é a “moeda de energia” da célula, e é assim que o músculo tem energia rápida.</p></div></div><h4>De onde vem a creatina de fora</h4><div class="grid"><div class="card"><span class="tag">Tem creatina</span><p>Carne vermelha, frango, peixe e porco. Ou seja, músculo: quando comemos carne, comemos creatina.</p></div><div class="card"><span class="tag">Não aumenta a creatina</span><p>Ovo e leite. A proteína do ovo é a albumina, e nenhum dos dois tem músculo esquelético.</p></div><div class="card"><span class="tag">Quem precisa suplementar</span><p>Veganos e vegetarianos, cuja dieta tem pouca ou nenhuma creatina. São o primeiro público com indicação real.</p></div></div><div class="box orange"><div class="kick"><span class="dot"></span>Parêntese da professora</div><p>Ainda não há comprovação (em artigos ou metanálises) de que a creatina melhore a demência de Alzheimer ou a depressão.</p></div><h4>Suplementação: o que diz a evidência</h4><p class="nota">Fonte citada: UpToDate, atualização de setembro de 2026, e posição do Colégio Americano de Medicina Esportiva.</p><div class="grid"><div class="card"><span class="tag">A favor</span><ul><li>A suplementação é ergogênica: melhora o desempenho.</li><li>Pode ser usada em exercícios de alta performance, em grupo ou individualmente.</li><li>Funciona em treinos de explosão rápida.</li></ul></div><div class="card"><span class="tag">Os limites</span><ul><li>Mais de 30% das pessoas não respondem: não ganham massa muscular com ela.</li><li>Aumentar a dose não aumenta a resposta.</li><li>O músculo guarda só 25 a 30% da creatina suplementada.</li><li>Não funciona em outros tipos de treino.</li><li>Talvez valha mais comer bem antes do treino.</li></ul></div></div><h4>Da conversa em sala</h4><ul><li><b>Recuperação mais do que força.</b> A creatina parece ajudar mais na recuperação muscular do que na explosão. A exceção é o atleta de alta performance, para quem frações de segundo decidem o pódio.</li><li><b>Precisa de muita água</b> para funcionar.</li><li><b>O “inchaço”</b> que alguns sentem é retenção de água dentro do músculo, não músculo novo. O que aumenta a massa muscular é a constância no exercício.</li><li><b>Doses altas.</b> Em atletas de alta performance, doses de 20 g parecem melhorar um pouco a dor muscular e a recuperação, porque entregam mais fosfato ao músculo.</li><li><b>Idoso com sarcopenia</b> que se cansa de mastigar carne: tem certa indicação quando começa a se exercitar.</li></ul><div class="quote"><p>“Não dá só para pensar que vai tomar uma capsulinha e tudo vai dar certo.”</p><div class="who">Dra. Vanessa, sobre olhar o todo: exercício, alimentação e sono</div></div><h3 class="sec-h"><span class="sn">06</span>Creatinina, massa muscular e taxa de filtração glomerular</h3><p>A creatinina depende da quantidade de músculo. Então duas pessoas saudáveis podem ter creatininas bem diferentes.</p><div class="grid"><div class="card"><span class="tag">Colega alto e musculoso</span><p>Cerca de 1,85 m e 86 a 87 kg. Tem mais massa muscular, então tende a ter creatinina mais alta.</p></div><div class="card"><span class="tag">Colega menor</span><p>Cerca de 1,64 m e 50 kg. Tem menos massa muscular, então tende a ter creatinina bem mais baixa. As mulheres, em geral, têm menos massa muscular.</p></div></div><p>Isso quer dizer que um dos dois tem o rim pior? Não. Quer dizer só que os dois têm massas musculares diferentes.</p><h4>Então como saber se o rim é bom?</h4><p>Além da creatinina, é preciso levar em conta o tamanho, o peso e a massa muscular da pessoa. E, principalmente, medir o quanto ela consegue filtrar de creatinina na urina de 24 horas. Isso é a <b>depuração de creatinina</b> (o “clearance”), também chamada de taxa de filtração glomerular: a capacidade de filtrar do rim ao longo das 24 horas do dia.</p><div class="ref"><div class="txt"><div class="kick"><span class="dot"></span>Valor normal · taxa de filtração glomerular</div><p>A meta para os dois colegas, mesmo com creatininas diferentes. A professora traduz como “mais de 90% do rim funcionando”.</p></div><div class="val">&gt; 90</div></div><div class="card wide"><span class="tag">Cistatina C</span><p>Exame mais novo que não depende da massa muscular. É mais eficaz que a creatinina, mas bem mais caro. Os convênios em geral não pagam, e o paciente tem que pagar particular. É útil nos casos duvidosos.</p></div><div class="box purple"><div class="kick"><span class="dot"></span>Complemento: fora da aula</div><p>A taxa de filtração glomerular é expressa em mililitros por minuto por 1,73 m² de superfície corporal. O valor “90” da aula está nessa unidade. A cistatina C é uma proteína produzida em ritmo constante por praticamente todas as células do corpo, e é por isso que ela não depende do músculo.</p></div><div class="es big"><div class="kick">A regra de ouro da aula <span class="prova">PROVA</span></div><p class="lead">Paciente com ureia alta e creatinina alta: pense em duas coisas.</p><div class="cells"><div class="cell"><div class="lab">Entrada</div><p>A ingestão está muito alta.</p></div><div class="cell"><div class="lab">Saída</div><p>O filtro, que é o rim, não está funcionando.</p></div><div class="cell"><div class="lab">Ou as duas</div><p>As duas coisas ao mesmo tempo.</p></div></div></div><h3 class="sec-h"><span class="sn">07</span>O essencial da aula</h3><h4>Números da aula</h4><div class="tiles"><div class="tile g"><div class="lab">Diurese normal</div><div class="n">2.100 a 2.800 mL</div><div class="s">em 24 horas, adulto de 70 kg</div></div><div class="tile r"><div class="lab">Oligúria</div><div class="n">&lt; 400 mL</div><div class="s">em 24 horas; na anúria, 0 mL</div></div><div class="tile r"><div class="lab">Poliúria</div><div class="n">&gt; 3.000 mL</div><div class="s">em 24 horas</div></div><div class="tile g"><div class="lab">Ureia</div><div class="n">10 a 40 mg/dL</div><div class="s">no sangue do adulto</div></div><div class="tile g"><div class="lab">Creatinina</div><div class="n">&lt; 1,2 mg/dL</div><div class="s">ideal abaixo de 1,0; laboratórios: 0,8 a 1,3</div></div><div class="tile g"><div class="lab">Taxa de filtração</div><div class="n">&gt; 90</div><div class="s">“mais de 90% do rim funcionando”</div></div><div class="tile"><div class="lab">Creatina produzida</div><div class="n">≈ 1 g por dia</div><div class="s">sem esforço, só por existir</div></div><div class="tile"><div class="lab">Ácido úrico no rim</div><div class="n">90% volta</div><div class="s">reabsorvido no túbulo proximal</div></div><div class="tile"><div class="lab">Saída do ácido úrico</div><div class="n">3/4 e 1/4</div><div class="s">pelo rim e pelo intestino</div></div></div><h4>A aula em uma linha por tema</h4><div class="linhas termos"><div class="ln"><div class="k">Diurese</div><div class="v">Normal de 2.100 a 2.800 mL em 24 horas (adulto de 70 kg). Oligúria abaixo de 400 mL. Poliúria acima de 3.000 mL. Anúria: não urina.</div></div><div class="ln"><div class="k">Diálise</div><div class="v">Os pacientes vivem em anúria ou oligúria.</div></div><div class="ln"><div class="k">Glomérulo</div><div class="v">Avaliado por ureia, creatinina, depuração de creatinina e proteína na urina.</div></div><div class="ln"><div class="k">Túbulo</div><div class="v">Avaliado pelo exame de urina: densidade, osmolaridade, sódio e potássio urinários.</div></div><div class="ln"><div class="k">Ureia</div><div class="v">Proteína → amônia tóxica → fígado (ciclo da ureia) → ureia → rim. Normal de 10 a 40 mg/dL. O acúmulo dá a síndrome urêmica.</div></div><div class="ln"><div class="k">Ácido úrico</div><div class="v">Via das xantinas. 3/4 sai pelo rim, 90% é reabsorvido no túbulo proximal. Sobe com álcool, carnes, frutos do mar, lise tumoral e insuficiência renal.</div></div><div class="ln"><div class="k">Creatina</div><div class="v">Rim (arginina + glicina) → fígado (+ metionina) → músculo. Cerca de 1 g por dia. Vem da carne. Ovo e leite não aumentam a creatina.</div></div><div class="ln"><div class="k">Creatinina</div><div class="v">Resto da creatina do músculo. Livremente filtrada, não reabsorvida, pouco secretada. Normal abaixo de 1,2 (ideal abaixo de 1,0).</div></div><div class="ln"><div class="k">Filtração</div><div class="v">A creatinina depende da massa muscular. Para julgar o rim, use a taxa de filtração glomerular (acima de 90) ou, nos casos duvidosos, a cistatina C.</div></div><div class="ln"><div class="k">Regra de ouro</div><div class="v">Ureia e creatinina altas: ingestão alta, rim que não filtra, ou os dois.</div></div></div><h4>Mapa da aula</h4><p class="nota">Cada linha segue um produto, da origem até a saída.</p><div class="cmp-wrap"><table class="cmp mapa"><thead><tr><th></th><th>Dieta e intestino</th><th>Músculo</th><th>Fígado</th><th>Rim</th><th>Saída</th></tr></thead><tbody><tr><td>Ureia</td><td>Proteínas da dieta e do corpo viram amônia</td><td>Amônia sai do músculo como alanina</td><td>Ciclo da ureia: a amônia vira ureia</td><td>A ureia é filtrada</td><td>Sai na urina</td></tr><tr><td>Ácido úrico</td><td>Dieta: carnes, frutos do mar, álcool</td><td class="muted">–</td><td>Via das xantinas: o fígado fabrica ácido úrico</td><td>Filtrado; 90% volta no túbulo proximal</td><td>3/4 pela urina, 1/4 pelo intestino</td></tr><tr><td>Creatina e creatinina</td><td>Carne tem creatina</td><td>3 · Guarda como fosfocreatina<br>4 · Quebra em creatinina, em ritmo constante</td><td>2 · + metionina = creatina</td><td>1 · Arginina + glicina viram ácido guanidinoacético<br>5 · Creatinina livremente filtrada, não reabsorvida</td><td>Sai na urina</td></tr></tbody></table></div><div class="box red"><div class="kick"><span class="dot"></span>Erros comuns</div><ul><li><b>Achar que creatinina mais alta sempre é doença renal.</b> Pode ser só mais massa muscular ou muita creatina ingerida.</li><li><b>Comparar a creatinina de duas pessoas</b> sem considerar o tamanho e o músculo de cada uma.</li><li><b>Achar que dieta pobre em proteína é boa</b> porque baixa a ureia. Ela prejudica a imunidade e a cicatrização.</li><li><b>Achar que ovo e leite dão creatina.</b> Nenhum dos dois tem músculo esquelético.</li><li><b>Achar que o “inchaço” da creatina é ganho de músculo.</b> É água retida dentro do músculo.</li><li><b>Aumentar a dose de creatina</b> esperando mais resultado. A resposta não aumenta com a dose.</li></ul></div><h4>Palavras da aula em linguagem simples</h4><div class="linhas termos"><div class="ln"><div class="k">Catabolismo</div><div class="v">Quebra de moléculas grandes (como as proteínas) em pedaços menores.</div></div><div class="ln"><div class="k">Depuração (clearance)</div><div class="v">Volume de sangue que o rim consegue “limpar” de uma substância em um certo tempo.</div></div><div class="ln"><div class="k">Desaminação</div><div class="v">Retirada do grupo amina, a parte com nitrogênio, de um aminoácido. É dela que sai a amônia.</div></div><div class="ln"><div class="k">Ergogênico</div><div class="v">Que melhora o desempenho físico.</div></div><div class="ln"><div class="k">Glomerulopatia</div><div class="v">Doença do glomérulo, o filtro do rim.</div></div><div class="ln"><div class="k">Hiperuricemia</div><div class="v">Ácido úrico alto no sangue.</div></div><div class="ln"><div class="k">Osmolaridade</div><div class="v">Quantidade de partículas dissolvidas em um líquido. Na urina, mostra o quanto o rim concentra.</div></div><div class="ln"><div class="k">Sarcopenia</div><div class="v">Perda de massa e de força muscular, típica do idoso.</div></div><div class="ln"><div class="k">Síndrome de lise tumoral</div><div class="v">Morte rápida de muitas células de um tumor (em geral após quimioterapia), que joga no sangue grande quantidade de substâncias, entre elas as que viram ácido úrico.</div></div><div class="ln"><div class="k">Síndrome urêmica</div><div class="v">Conjunto de sintomas causados pelo acúmulo de ureia e de outras toxinas quando o rim para de filtrar.</div></div><div class="ln"><div class="k">Taxa de filtração glomerular</div><div class="v">Quanto os glomérulos filtram. É o melhor número para dizer quanto do rim está funcionando.</div></div></div>$ap$, 'nefrologia/aula-1.pdf');

insert into public.aulas (id, materia_id, ordem, titulo, resumo, apostila_html, pdf_caminho) values
  ('nefro-a2', 'nefro', 2, 'Doenças císticas dos rins e tumores renais', 'Cisto simples e Bosniak, doença policística, cistos da medula, cística adquirida e angiomiolipoma.',
$ap$<div class="legenda"><span class="lg"><i class="sw blue"></i>Conteúdo da aula</span><span class="lg"><i class="sw green"></i>Dose ou valor de referência</span><span class="lg"><i class="sw red"></i>Alerta, erro comum ou armadilha</span><span class="lg"><i class="sw orange"></i>Fala da professora</span><span class="lg"><i class="sw purple"></i>Complemento fora da aula</span></div><div class="tiles"><div class="tile r"><div class="lab">Bosniak IIF</div><div class="n">Encaminhar</div><div class="s">a partir desta categoria, o cisto vai obrigatoriamente para o especialista</div></div><div class="tile g"><div class="lab">Água</div><div class="n">Mais de 3 L</div><div class="s">por dia: o tratamento mais barato da doença policística</div></div><div class="tile"><div class="lab">Policística dominante</div><div class="n">60 anos</div><div class="s">idade em que metade dos adultos chega à insuficiência renal</div></div></div><h3 class="sec-h"><span class="sn">00</span>Recados da disciplina</h3><div class="linhas"><div class="ln"><div class="k">Chamada</div><div class="v">Coloque a data em todas as páginas da folha de chamada. A professora arquiva as folhas por data.</div></div><div class="ln"><div class="k">Gravação</div><div class="v">Pode gravar, mas a professora quer saber, porque envolve exposição de imagem. Basta uma pessoa avisar; ela confirma no começo da aula.</div></div><div class="ln"><div class="k">Provas</div><div class="v">A prova teórica do Dr. Guilherme vale 9 pontos. A prova da professora também vale 9.</div></div><div class="ln"><div class="k">Aula prática</div><div class="v">Vale 1 ponto: presença mais participação. É somado à nota do Dr. Guilherme só no fim do bimestre, para quem ainda não teve aula prática não ficar com zero.</div></div><div class="ln"><div class="k">Seminários</div><div class="v">São três: com o Dr. Guilherme (já aconteceu), com a Dra. Andressa e com a professora. Presença e participação nos três formam a nota de seminário, de 1 ponto, somada à prova da professora.</div></div><div class="ln"><div class="k">Retomada</div><div class="v">Toda aula começa com 5 minutos para dúvidas da aula anterior.</div></div><div class="ln"><div class="k">Slides</div><div class="v">Os slides das aulas 1 e 2 vão por e-mail. São atualizados de 12 a 24 horas antes de cada aula.</div></div><div class="ln"><div class="k">Próxima aula</div><div class="v">Doenças vasculares dos rins. É a aula mais pesada da disciplina: pouca imagem, conteúdo denso, exige raciocínio.</div></div></div><div class="quote"><p>“É para tornar igual os iguais. Isso se chama democracia.”</p><div class="who">A professora, sobre somar o ponto da aula prática só no fim do bimestre</div></div><div class="box"><div class="kick"><span class="dot"></span>O que ela pediu para guardar e o que é só para conhecer</div><ul><li><b>Guardar na cabeça:</b> a doença renal policística autossômica dominante, nas palavras dela, “essa sim”.</li><li><b>Saber pelo menos quando encaminhar:</b> o cisto renal, pela classificação de Bosniak.</li><li><b>Estudar um pouco mais:</b> o rim em esponja medular.</li><li><b>Só saber que existe:</b> a doença policística autossômica recessiva e a nefronoftise.</li><li><b>Tumores renais:</b> são da urologia. Na aula, só o angiomiolipoma foi aprofundado.</li><li><b>“Bolinha”</b> é para entender o que é um cisto, não para escrever na prova.</li></ul></div><h3 class="sec-h"><span class="sn">01</span>Dúvida da aula passada: de onde vem a creatina</h3><p>A creatina, a substância que no músculo dá origem à creatinina estudada na aula 1, chega ao corpo por três caminhos:</p><div class="grid"><div class="card"><span class="tag">Via 1 · Produção própria</span><p>O corpo produz creatina o tempo inteiro a partir de três aminoácidos, mesmo com a pessoa sentada, parada.</p></div><div class="card"><span class="tag">Via 2 · Alimentação</span><p>Quem come carne ganha mais creatina. Ovo e leite não contam: o ovo tem albumina, o leite tem outras proteínas.</p></div><div class="card"><span class="tag">Via 3 · Suplementação</span><p>Quem toma o suplemento ganha mais creatina, somada à que já produz.</p></div></div><h4>Veganos e vegetarianos</h4><p>Eles não têm a via da alimentação. Só o que produzem por conta própria não dá conta do gasto do músculo, principalmente se fazem exercício físico; por isso precisam obrigatoriamente suplementar. Quanto suplementar depende de quanto a pessoa gasta, se faz exercício e do porte físico. O idoso com perda de massa muscular (sarcopenia) também precisa de avaliação individual.</p><div class="quote"><p>“Nesse caso é individualizado. Não tem fórmula de bolo, infelizmente.”</p><div class="who">A professora, sobre a dose de creatina para veganos e vegetarianos</div></div><div class="box purple"><div class="kick"><span class="dot"></span>Complemento: fora da aula</div><p>Os três aminoácidos são a glicina, a arginina e a metionina. A produção começa nos rins e termina no fígado; o músculo é onde a creatina fica guardada (cerca de 95% do total do corpo). Ali, todos os dias, uma pequena parte (cerca de 1 a 2%) se transforma sozinha em creatinina, que sai pela urina.</p></div><h3 class="sec-h"><span class="sn">02</span>Cistos renais, cisto simples e classificação de Bosniak</h3><h4>O que é um cisto</h4><p>Cisto é uma cavidade delimitada por epitélio e preenchida por líquido. Pode estar no córtex ou na medula do rim, ter tamanhos variados, aparecer na infância ou no adulto, e ser silencioso ou dar sintomas. Em bom português, são as “bolinhas” de líquido dentro do rim.</p><div class="grid"><div class="card"><span class="tag">Sintomas</span><p>A maioria não dá sintoma. Quando dão, podem causar hematúria (sangue na urina), hipertensão, obstrução urinária, dor lombar ou perda da função renal.</p></div><div class="card"><span class="tag">Origem</span><ul><li><b>Hereditários ou genéticos:</b> autossômicos dominantes, autossômicos recessivos ou ligados ao cromossomo X.</li><li><b>Não hereditários:</b> os cistos adquiridos e os que vêm de uma desordem do desenvolvimento.</li></ul></div></div><h4>Cisto simples</h4><p>É a mais comum das doenças císticas: de 65 a 70% de todas. Não é hereditário. Costuma medir de 0,5 a 1 cm, mas pode chegar a 4 ou 5 cm. Tem limites precisos, é esférico, tem uma só cavidade (unilocular) e parede fina e lisa. É o cisto da vida adulta e é mais comum em homens do que em mulheres.</p><div class="tiles"><div class="tile"><div class="lab">Entre as doenças císticas</div><div class="n">65 a 70%</div><div class="s">são cistos simples</div></div><div class="tile"><div class="lab">Aos 40 anos</div><div class="n">5%</div><div class="s">da população tem cisto simples</div></div><div class="tile"><div class="lab">Aos 80 anos</div><div class="n">30 a 36%</div><div class="s">quase 40% da população</div></div></div><p>Geralmente não dá sintoma, mas pode sangrar e causar hematúria; raramente causa hipertensão ou infecção. O diagnóstico é feito por ultrassom, tomografia computadorizada ou ressonância magnética, e a conduta é observar: uma reavaliação por ano.</p><div class="box"><div class="kick"><span class="dot"></span>Como ele costuma aparecer</div><p>Como não dói, quase sempre é achado de exame. Exemplo da aula: o paciente vai ao gastroenterologista com náusea, vômito e má digestão, com suspeita de cálculo na vesícula. Na ecografia do abdome, o ecografista encontra um cisto simples no rim.</p></div><div class="box red"><div class="kick"><span class="dot"></span>Quando o cisto simples deixa de ser simples</div><p>Se o cisto muda de características, o acompanhamento fica mais de perto e, às vezes, é preciso operar (a cirurgia é do urologista e se chama marsupialização):</p><ul><li>a membrana do cisto fica mais grossa;</li><li>aparece líquido diferente dentro dele, com sinais de sangramento ou de descolamento da membrana (algo “boiando” dentro do cisto);</li><li>surge um nível de líquido dentro do cisto, sinal de que já houve sangramento;</li><li>o cisto fica muito grande ou cresce demais.</li></ul></div><h4>Classificação de Bosniak: quando encaminhar</h4><p>Criada em 1986 e atualizada com frequência desde então, a classificação de Bosniak vem descrita no laudo de ultrassom, de tomografia e de ressonância. Mesmo quem não vai ser urologista nem nefrologista precisa saber quando encaminhar um paciente com cisto. Em aula, a categoria IIF foi chamada de “2F”. Parede mais grossa, mais septos e mais resíduos dentro: o risco de câncer aumenta.</p><div class="bosniak"><div class="bk ok"><b>Bosniak I</b><p><span class="lab">Como é</span>Cisto simples: bolinha de parede fina e lisa, sem nada dentro.</p><p><span class="lab">Conduta</span>Repetir a ecografia em 6 a 12 meses.</p></div><div class="bk ok"><b>Bosniak II</b><p><span class="lab">Como é</span>Benigno, mas já com alguns septos finos e um pouco de calcificação.</p><p><span class="lab">Conduta</span>Repetir a ecografia em 6 a 12 meses.</p></div><div class="bk alerta"><b>Bosniak IIF</b><p><span class="lab">Como é</span>Mais calcificação e mais resíduos dentro. Pode evoluir para o III.</p><p><span class="lab">Conduta</span>Somar a tomografia e acompanhar por 5 anos, com mais frequência.</p></div><div class="bk alerta"><b>Bosniak III</b><p><span class="lab">Como é</span>Grosseiro: muitos resíduos e descolamento de membrana. Pode virar câncer.</p><p><span class="lab">Conduta</span>Tomografia e ressonância; às vezes repetir em 3, 6 e 12 meses.</p></div><div class="bk alerta"><b>Bosniak IV</b><p><span class="lab">Como é</span>Considerado câncer em 85 a 100% dos casos.</p><p><span class="lab">Conduta</span>Cirurgia direto.</p></div></div><div class="bk-legenda"><span class="ok">I e II: pode ser acompanhado na atenção básica, uma vez por ano</span><span class="alerta">IIF, III e IV: encaminhar obrigatoriamente ao nefrologista ou urologista</span></div><div class="es"><div class="kick">Na prática: o laudo chegou com um cisto</div><p class="lead">Numa cidade pequena, você investiga uma dor abdominal. A ecografia mostra cálculo na vesícula e, de quebra, um cisto no rim. Leia a categoria de Bosniak no laudo.</p><div class="cells"><div class="cell"><div class="lab">Bosniak I ou II</div><p>Não precisa encaminhar. Acompanhe você mesmo, com ecografia uma vez por ano. Exemplo: “cisto simples Bosniak I, de 0,6 cm”.</p></div><div class="cell"><div class="lab">Bosniak IIF</div><p>Encaminhe obrigatoriamente ao especialista. Vai precisar de tomografia e de acompanhamento por 5 anos.</p></div><div class="cell"><div class="lab">Bosniak III ou IV</div><p>Encaminhe: o risco de câncer é real. Tomografia com ressonância e, no IV, cirurgia direto.</p></div></div></div><div class="box purple"><div class="kick"><span class="dot"></span>Complemento: fora da aula</div><p>Na literatura, o risco estimado de câncer é praticamente nulo nas categorias I e II, de cerca de 5 a 10% na IIF e de cerca de 50% na III. A versão mais recente da classificação é de 2019.</p></div><h3 class="sec-h"><span class="sn">03</span>Doença policística autossômica recessiva</h3><p>É uma doença rara e de quadro grave: de 1 em cada 20.000 a 1 em cada 55.000 nascimentos, conforme o livro. A professora viu um único caso até hoje. Basta saber que ela existe.</p><h4>Onde ficam os cistos</h4><p>Essencialmente nos ductos coletores. Lembre a sequência do néfron: glomérulo → túbulo proximal → alça de Henle descendente → alça de Henle ascendente → túbulo distal → ducto coletor. Imagine vários cistos entupindo o coletor: a urina não drena, volta para trás e vai destruindo os túbulos.</p><h4>Herança</h4><p>Para a criança ter a doença, os dois pais precisam carregar o gene recessivo, e é por isso que ela é rara. Para quem vai fazer pediatria, este número importa, porque a família vai perguntar se o próximo filho também pode ter a doença:</p><div class="ref"><div class="txt"><div class="kick"><span class="dot"></span>Chance de outro filho com a doença</div><p>Quando os dois pais carregam o gene recessivo.</p></div><div class="val">1 em 4<small>25% a cada gestação</small></div></div><div class="card wide"><span class="tag">No recém-nascido</span><ul><li>Oligoidrâmnio: pouco líquido amniótico na gestação.</li><li>Falha no desenvolvimento dos ductos coletores.</li><li>Dilatação cística das vias biliares do fígado: a obstrução não é só dos coletores do rim.</li><li>Cerca de 60% dos bebês diagnosticados ao nascer evoluem para doença renal crônica até o quarto mês de vida.</li></ul></div><h3 class="sec-h"><span class="sn">04</span>Policística dominante: causa e quadro clínico</h3><p>Ao contrário da anterior, esta é a doença que a professora pediu para guardar. Foi a doença da paciente Sandra, da aula prática anterior ao recesso.</p><div class="tiles"><div class="tile"><div class="lab">Frequência</div><div class="n">1 em 400 a 1.000</div><div class="s">nascimentos: doença genética comum</div></div><div class="tile"><div class="lab">Quando aparece</div><div class="n">30 a 40 anos</div><div class="s">os cistos já existem desde a vida intrauterina</div></div><div class="tile r"><div class="lab">Insuficiência renal</div><div class="n">50% aos 60 anos</div><div class="s">dos adultos, para mais ou para menos</div></div></div><p>Os cistos podem aparecer em qualquer parte do néfron (diferente da recessiva, que fica no coletor), atingem sempre os dois rins e aumentam de número e de tamanho com o tempo de vida.</p><div class="box orange"><div class="kick"><span class="dot"></span>Parêntese da professora: a pipoca</div><p>É como se a pessoa nascesse com grãozinhos de pipoca dentro do rim. Entre os 30 e os 40 anos, as pipoquinhas explodem e viram grandes cistos, e o rim fica tomado por eles.</p></div><p>Se os cistos tomam todo o parênquima renal, não importa onde estejam (córtex, medula, túbulo proximal ou distal), o rim vai perdendo função. “Não precisa ser nefrologista, só pensar pela lógica.”</p><h4>Por que acontece: os genes PKD1 e PKD2</h4><p>A doença vem da mutação de um de dois genes, chamados PKD1 (que produz a policistina 1) e PKD2 (que produz a policistina 2). O mais comum é a alteração do PKD1, em 85% dos casos; ele fica no braço curto do cromossomo 16. A policistina é um receptor e transdutor de sinal: recebe sinais de fora da célula e os transmite para dentro.</p><h4>Na verdade, uma doença sistêmica</h4><p>Todo mundo tem policistina; quem tem a doença tem uma policistina que funciona mal. E ela não existe só no rim: está no fígado, no pâncreas, nos ovários, nos testículos, nas valvas do coração, no olho, no intestino e no cérebro. Por isso quem tem doença policística tem alterações em todos esses órgãos. Segundo a professora, o nome deveria ser “doença sistêmica policística”; ficou “renal” por causa do impacto: os cistos tomam o rim e levam à insuficiência renal por volta dos 55 a 60 anos.</p><h4>Fisiopatologia</h4><ol class="flow"><li><b>Policistina mutada e reduzida.</b> É genética e hereditária: não se escolhe ter, e normalmente passa de pais para filhos.</li><li><b>Alteração da maturação das células.</b> As células do túbulo não amadurecem direito.</li><li><b>Quatro defeitos ao mesmo tempo.</b> Crescimento celular descontrolado; matriz extracelular anormal, com a membrana basal espessada; acúmulo de líquido; defeito na adesão entre as células.</li><li><b>Cistos.</b> O líquido que drenaria como urina fica preso dentro deles.</li></ol><p>O esquema “doméstico” da aula: as células do túbulo ficam uma ao lado da outra, formando um tubo reto. Onde há uma célula com policistina alterada, a parede se dilata e se fecha. O túbulo fica como um rosário de cistos, e o rim, com o tempo, fica como um queijo suíço.</p><h4>Sinais e sintomas</h4><div class="grid"><div class="card"><span class="tag">Primeiro sintoma</span><h5>Dor lombar</h5><p>Os cistos crescem, o rim aumenta e distende a cápsula que o envolve (a cápsula de Gerota). Não é o rim que cresce: são os cistos.</p></div><div class="card"><span class="tag">Sangramento</span><h5>Hematúria</h5><p>Ao crescer, os cistos podem sangrar ou romper. A hematúria pode ser visível ou só no exame, e às vezes dura 2 a 3 dias.</p></div></div><div class="box red"><div class="kick"><span class="dot"></span>Armadilha</div><p>Nem toda dor lombar é cálculo renal. No paciente policístico, ela vem da distensão do rim pelos cistos.</p></div><p>As causas da hematúria no policístico são a ruptura de um cisto para dentro da pelve renal, a infecção urinária, o cálculo e, mais raramente, o tumor.</p><div class="grid"><div class="card"><span class="tag">Até 20%</span><h5>Cálculos nos cistos</h5><p>Os cistos podem calcificar e formar cálculos dentro deles.</p></div><div class="card"><span class="tag">Até 25%</span><h5>Valvas do coração</h5><p>A policistina também está nas valvas cardíacas, que podem se alterar.</p></div><div class="card"><span class="tag">Fora do rim</span><h5>Aneurismas</h5><p>Aneurisma cerebral e cistos perto de vasos, que podem levar a aneurisma.</p></div></div><div class="box red"><div class="kick"><span class="dot"></span>Investigar aneurisma cerebral</div><p>A diretriz internacional de nefrologia (KDIGO), na atualização de 2025, determina que o paciente com doença renal policística seja investigado para aneurisma cerebral, pelo risco de acidente vascular cerebral hemorrágico.</p></div><h4>Hipertensão</h4><p>Mais de 50% desses pacientes são hipertensos. O mecanismo:</p><ol class="flow"><li><b>Os cistos apertam a mácula densa.</b> Eles se espalham por qualquer parte do rim e espremem essa região do túbulo.</li><li><b>Ativa o sistema renina-angiotensina-aldosterona.</b> O rim passa a reter mais sal e água.</li><li><b>A pressão sobe e piora a doença.</b> A hipertensão aparece cedo, antes da perda de função renal, e é um fator de progressão: quanto mais hipertenso, mais grave a evolução.</li></ol><h4>Insuficiência renal</h4><p>Pode ser aguda, por obstrução urinária (coágulo ou compressão), mas normalmente é crônica, pela destruição progressiva do parênquima pelos cistos. Em média, o paciente vai perdendo função até os 60 anos; dali em diante, cada ano que passa aumenta a chance de perder a função.</p><div class="grid"><div class="card red"><span class="tag">Piora mais rápido</span><h5>Gene PKD1</h5><p>Pior quando a alteração é na policistina 1.</p></div><div class="card red"><span class="tag">Piora mais rápido</span><h5>Homens</h5><p>A evolução é pior no sexo masculino.</p></div><div class="card red"><span class="tag">Piora mais rápido</span><h5>Já hipertenso</h5><p>Quem já tinha pressão alta quando descobriu a doença.</p></div></div><div class="box"><div class="kick"><span class="dot"></span>Característica da doença</div><p>A taxa de filtração glomerular cai mais rápido na doença policística do que em qualquer outra doença renal. É a que evolui mais rapidamente para a falência da função renal.</p></div><h3 class="sec-h"><span class="sn">05</span>Policística dominante: diagnóstico e tratamento</h3><h4>Como se faz o diagnóstico</h4><p>Duas pistas: a quantidade de cistos (quanto mais cistos, maior a chance de ser policística) e a história familiar. A paciente Sandra tem a doença, e também o irmão, o pai, o tio e o primo. “Quer história familiar mais positiva do que essa? E é só perguntar.”</p><p>No ultrassom ou na tomografia, o número de cistos esperado muda com a idade. É a maneira prática de saber que não é só um cisto simples, e sim doença policística:</p><div class="tiles"><div class="tile"><div class="lab">15 a 29 anos</div><div class="n">2 ou mais cistos</div><div class="s">no total, num rim só ou um em cada rim</div></div><div class="tile"><div class="lab">30 a 59 anos</div><div class="n">2 ou mais</div><div class="s">cistos em cada rim</div></div><div class="tile"><div class="lab">60 anos ou mais</div><div class="n">4 ou mais</div><div class="s">cistos em cada rim</div></div></div><div class="card wide"><span class="tag">Critérios secundários</span><p>Achados que reforçam o diagnóstico:</p><ul class="cols2"><li>fígado policístico (cistos no fígado);</li><li>insuficiência renal;</li><li>hérnia abdominal ou inguinal;</li><li>lesões das valvas cardíacas;</li><li>cistos no pâncreas;</li><li>aneurisma das artérias cerebrais, com alto risco de sangramento;</li><li>cisto de vesícula seminal;</li><li>pálpebra caída (ptose palpebral) com cisto no olho.</li></ul></div><div class="box purple"><div class="kick"><span class="dot"></span>Complemento: fora da aula</div><p>Os critérios por idade são os critérios de Ravine, pensados para quem tem história familiar da doença. Existe uma versão revisada, os critérios de Pei: de 15 a 39 anos, 3 ou mais cistos no total; de 40 a 59 anos, 2 ou mais em cada rim; a partir dos 60, 4 ou mais em cada rim.</p></div><div class="grid"><div class="card"><span class="tag">De rotina</span><h5>Exames de imagem</h5><p>Ultrassom (que vê bem os cistos), tomografia computadorizada e ressonância magnética. Com imagem e história familiar se fazem excelentes diagnósticos.</p></div><div class="card"><span class="tag">Existe, mas não é usual</span><h5>Teste genético</h5><p>Pode ser colhido em Cascavel e enviado a São Paulo, o maior centro de testes genéticos. É caríssimo e não faz parte da prática habitual.</p></div></div><h4>Tratamento</h4><p>É uma doença hereditária: o tratamento é dos sintomas, não da doença em si, somado a medidas para frear a formação dos cistos.</p><div class="linhas"><div class="ln"><div class="k">Dor</div><div class="v">Primeiro, repouso e analgesia. Se não melhorar, punção do cisto ou cirurgia. Quando é preciso operar, o melhor é retirar o rim inteiro, porque ele é muito frágil: se tirar um cisto, não sobra estrutura para segurar os outros.</div></div><div class="ln"><div class="k">Pressão e inchaço</div><div class="v">Dieta pobre em sal e anti-hipertensivos: inibidores da enzima conversora de angiotensina, bloqueadores do receptor de angiotensina, bloqueadores dos canais de cálcio ou betabloqueadores.</div></div><div class="ln"><div class="k">Hematúria</div><div class="v">Repouso por 24 a 48 horas, que geralmente resolve. Se não melhorar, o urologista faz uma pequena descompressão do cisto.</div></div><div class="ln"><div class="k">Cisto infectado</div><div class="v">Antibiótico lipossolúvel: quinolona (ciprofloxacino, norfloxacino, levofloxacino), cloranfenicol ou sulfametoxazol com trimetoprima.</div></div></div><div class="box orange"><div class="kick"><span class="dot"></span>Parêntese da professora: spoiler da aula de infecção urinária</div><p>As sulfas, “da idade da minha avó”, voltaram com força: hoje são primeira linha no mundo para tratar infecção urinária. Ficaram anos sem uso, e as bactérias atuais não as “reconhecem” mais; por isso voltaram a matar. Já as quinolonas estão sendo restringidas pelos protocolos internacionais para a cistite, porque foram usadas abusivamente. Elas ficam para infecções graves: pielonefrite, não cistite simples.</p></div><h4>Água e café: o tratamento mais barato</h4><p>Quanto mais fluxo de urina, mais os túbulos ficam abertos e menos tempo a policistina alterada tem para agir; com isso, menos cistos se formam. Já a cafeína estimula a formação de cistos: não é preciso cortar totalmente, mas há um teto.</p><div class="ref"><div class="txt"><div class="kick"><span class="dot"></span>Policística dominante</div><p>Hidratação alta e cafeína limitada, todos os dias.</p></div><div class="vals"><div class="val"><small>Água</small>Mais de 3 L/dia</div><div class="val"><small>Café ou cafeína</small>Até 200 mL/dia</div></div></div><h4>Tolvaptana: o remédio que ainda não chegou</h4><p>A tolvaptana é um antagonista do receptor V2 do hormônio antidiurético e reconhecidamente diminui a produção de cistos. O raciocínio: bloqueia o hormônio antidiurético → o paciente urina mais → o túbulo fica aberto → menos cistos.</p><p>Ela é usada no resto do mundo há uns 5 ou 6 anos e já existe em países vizinhos, mas ainda não no Brasil. A Agência Nacional de Vigilância Sanitária foi cautelosa porque, em alguns pacientes, o remédio evitou cistos no rim mas aumentou os cistos no fígado. A expectativa é que chegue ao país nos próximos 2 anos.</p><div class="box purple"><div class="kick"><span class="dot"></span>Complemento: fora da aula</div><p>Na literatura, o efeito adverso hepático mais descrito da tolvaptana é a lesão do fígado (aumento das enzimas hepáticas), o que exige exames de sangue periódicos. Como faz urinar muito, também causa sede intensa e grande volume de urina.</p></div><h4>Enquanto o paciente espera o nefrologista</h4><p>Você suspeita de rim policístico e encaminha, mas a fila do consórcio de saúde (aqui em Cascavel, o CISOP) é de 4 meses. A resposta começa pelo trabalho dele: o movimento repetitivo de impacto pode romper um cisto e fazer o paciente sangrar pela urina.</p><div class="grid"><div class="card"><span class="tag">Vaqueiro</span><h5>Diminuir o trote</h5><p>Anda a cavalo todo dia: o sobe e desce do trote pode romper um cisto.</p></div><div class="card"><span class="tag">Motoboy</span><h5>Ir mais devagar</h5><p>O vaivém da moto cortando os carros também traumatiza o rim.</p></div><div class="card"><span class="tag">Professor de jump</span><h5>Ensaiar fora da cama</h5><p>Pular três aulas por dia aumenta a chance de o cisto sangrar.</p></div></div><div class="es big"><div class="kick">A regra de ouro da aula</div><p class="lead">O paciente policístico não espera a consulta de mãos vazias: ele sai do seu consultório orientado.</p><div class="cells"><div class="cell"><div class="lab">Evitar microtraumas</div><p>Reduzir o impacto no trabalho e no exercício para não romper cistos.</p></div><div class="cell"><div class="lab">Beber água</div><p>Mais de 3 L por dia, para manter os túbulos abertos.</p></div><div class="cell"><div class="lab">Limitar a cafeína</div><p>No máximo 200 mL de café ou outra fonte de cafeína por dia.</p></div></div><p class="foot">Quando esse paciente chega ao especialista já orientado, o tratamento anda mais rápido.</p></div><div class="quote"><p>“O que eu vou contar para vocês é por isso que professores existem.”</p><div class="who">A professora, sobre o que dizer ao paciente que espera a consulta</div></div><h3 class="sec-h"><span class="sn">06</span>Doenças císticas da medula renal</h3><p>São dois tipos: o rim em esponja medular, que vale estudar um pouco mais, e a nefronoftise, bem rara, da qual basta saber que existe.</p><h4>Rim em esponja medular</h4><p>Ocorre em menos de 1% da população, geralmente em adultos. É uma malformação dos ductos coletores na região dos cálices renais: há dilatação cística dos túbulos coletores só na medula, não no córtex, por um defeito do desenvolvimento. Não se sabe por que acontece. Pode aparecer como hematúria, cálculo renal ou infecção urinária; é uma causa rara de litíase. Em 25% dos pacientes, um lado do corpo é mais desenvolvido do que o outro (hemi-hipertrofia).</p><div class="box"><div class="kick"><span class="dot"></span>Como tratar</div><p>Não há tratamento específico, mas ele deve sempre ser tratado como um facilitador de cálculos renais. Alcalinizar a urina melhora o rim em esponja medular.</p></div><h4>Nefronoftise: só para saber que existe</h4><p>Distúrbio autossômico recessivo da infância, com quatro formas: esporádica não familiar, nefronoftise juvenil familiar, displasia renal-retiniana e doença cística medular do adulto. No rim há desintegração da membrana basal dos túbulos, atrofia dos túbulos, infiltrado e fibrose no interstício.</p><p>Na criança, causa poliúria, polidipsia, nefropatia perdedora de sal e acidose tubular renal. Em só 20% dos casos há manifestações fora do rim: retinite pigmentosa, fibrose do fígado e defeitos ósseos. É a causa mais comum de insuficiência renal na infância quando não se acha outra explicação. O diagnóstico é por biópsia renal, que mostra nefrite túbulo-intersticial crônica.</p><div class="cmp-wrap"><table class="cmp"><thead><tr><th></th><th>Rim em esponja medular</th><th>Nefronoftise</th></tr></thead><tbody><tr><td>Quem</td><td>Adultos; menos de 1% da população</td><td>Crianças; rara</td></tr><tr><td>Origem</td><td>Defeito do desenvolvimento, de causa desconhecida</td><td>Autossômica recessiva</td></tr><tr><td>Onde</td><td>Túbulos coletores da medula, perto dos cálices</td><td>Membrana basal dos túbulos e interstício</td></tr><tr><td>Clínica</td><td>Hematúria, cálculo, infecção urinária</td><td>Poliúria, polidipsia, perda de sal, acidose</td></tr><tr><td>Fora do rim</td><td>Hemi-hipertrofia em 25%</td><td>Retina, fígado e ossos em 20%</td></tr><tr><td>Conduta</td><td>Tratar como facilitador de cálculo; alcalinizar a urina</td><td>Diagnóstico por biópsia renal</td></tr></tbody></table></div><h3 class="sec-h"><span class="sn">07</span>Doença cística adquirida</h3><p>Depois das hereditárias, uma adquirida. É comum em quem faz diálise há muitos anos, seja hemodiálise, seja diálise peritoneal. Acontece por uremia (excesso de ureia no sangue), aumento de oxalato ou isquemia prolongada do rim. Os cistos ocupam cerca de 25% do parênquima, e geralmente são de 1 a 5 cistos.</p><div class="box red"><div class="kick"><span class="dot"></span>O mais importante</div><p>Esses cistos têm maior risco de virar câncer. Por isso, o paciente em hemodiálise ou diálise peritoneal precisa fazer exame de imagem para procurar cistos renais.</p></div><h3 class="sec-h"><span class="sn">08</span>Tumores renais e angiomiolipoma</h3><p>Os tumores renais são essencialmente da urologia; na aula de nefrologia, só “um pitaquinho”.</p><div class="grid"><div class="card"><span class="tag">Benignos</span><ul><li>cisto simples;</li><li>angiomiolipoma (ou hamartoma);</li><li>adenoma;</li><li>oncocitoma.</li></ul></div><div class="card"><span class="tag">Malignos</span><ul><li>carcinoma de células renais;</li><li>tumor de Wilms;</li><li>carcinoma da pelve renal.</li></ul><p class="nota">Um nome desta lista ficou inaudível na gravação; confira no slide.</p></div></div><h4>Angiomiolipoma (hamartoma)</h4><p>É um tumor mesenquimal feito de gordura, músculo liso e vasos sanguíneos, que toma conta de uma parte do rim. Corresponde a 3% dos tumores sólidos do rim, é mais comum em mulheres, entre os 50 e os 60 anos. Costuma ser único e de um lado só, com pouca clínica e sem dor: geralmente é achado de exame, no ultrassom ou na tomografia.</p><div class="grid"><div class="card red"><span class="tag">Preocupa</span><h5>Pobre em gordura</h5><p>Com pouca gordura e mais vaso e músculo, tem risco de transformação maligna.</p></div><div class="card red"><span class="tag">Preocupa</span><h5>Cresce rápido</h5><p>Aumenta mais de 2,5 mm por ano.</p></div><div class="card red"><span class="tag">Preocupa</span><h5>Sangra</h5><p>Se sangra, aparece hematúria.</p></div></div><div class="box purple"><div class="kick"><span class="dot"></span>Complemento: fora da aula</div><p>Na literatura, o angiomiolipoma pobre em gordura preocupa sobretudo porque, nos exames de imagem, fica difícil distingui-lo do carcinoma de células renais.</p></div><div class="ref"><div class="txt"><div class="kick"><span class="dot"></span>Mais chance de sangrar</div><p>Também com vasos grandes ou aneurismas dentro da lesão, e na gravidez.</p></div><div class="vals"><div class="val"><small>Tamanho</small>Maior que 6 cm</div><div class="val"><small>Crescimento</small>Mais de 2,5 mm/ano</div></div></div><div class="quote"><p>“Hematúria não é só litíase. Então, olhem a hematúria, macroscópica ou microscópica, com olhos muito refinados.”</p><div class="who">A professora, sobre como atender um paciente com hematúria</div></div><h4>Diagnóstico e acompanhamento</h4><p>O ultrassom é bom para rastrear, ou seja, para achar o angiomiolipoma, mas não mostra quanto de gordura ele tem. Depois do diagnóstico, o acompanhamento é por tomografia ou ressonância, a cada 6 ou 12 meses, para medir a velocidade de crescimento:</p><div class="grid"><div class="card"><span class="tag">Cresce devagar</span><h5>Menos de 2,5 mm por ano</h5><p>Exame de controle uma vez por ano.</p></div><div class="card red"><span class="tag">Cresce rápido</span><h5>Mais de 2,5 mm por ano</h5><p>Exame a cada 6 meses, com possibilidade de cirurgia para retirar.</p></div></div><h3 class="sec-h"><span class="sn">09</span>O essencial da aula</h3><h4>Números da aula</h4><div class="tiles"><div class="tile"><div class="lab">Cisto simples</div><div class="n">65 a 70%</div><div class="s">das doenças císticas; 5% aos 40 anos e 30 a 36% aos 80</div></div><div class="tile r"><div class="lab">Bosniak IV</div><div class="n">85 a 100%</div><div class="s">dos casos considerados câncer</div></div><div class="tile"><div class="lab">Policística recessiva</div><div class="n">1 em 4</div><div class="s">chance de outro filho afetado; doença rara</div></div><div class="tile"><div class="lab">Policística dominante</div><div class="n">1 em 400 a 1.000</div><div class="s">nascimentos</div></div><div class="tile"><div class="lab">Gene PKD1</div><div class="n">85%</div><div class="s">dos casos; cromossomo 16</div></div><div class="tile r"><div class="lab">Insuficiência renal</div><div class="n">50% aos 60 anos</div><div class="s">dos adultos com policística dominante</div></div><div class="tile"><div class="lab">Hipertensão</div><div class="n">Mais de 50%</div><div class="s">dos policísticos; aparece cedo</div></div><div class="tile"><div class="lab">Cálculos e valvas</div><div class="n">20% e 25%</div><div class="s">cálculos nos cistos; alteração de valva</div></div><div class="tile g"><div class="lab">Água e café</div><div class="n">3 L e 200 mL</div><div class="s">mais de 3 L de água; até 200 mL de café por dia</div></div><div class="tile"><div class="lab">Rim em esponja medular</div><div class="n">Menos de 1%</div><div class="s">da população; hemi-hipertrofia em 25%</div></div><div class="tile"><div class="lab">Cística adquirida</div><div class="n">1 a 5 cistos</div><div class="s">em cerca de 25% do parênquima, em diálise</div></div><div class="tile r"><div class="lab">Angiomiolipoma</div><div class="n">6 cm · 2,5 mm</div><div class="s">tamanho e crescimento por ano que aumentam o risco</div></div></div><h4>A aula em uma linha por tema</h4><div class="linhas termos"><div class="ln"><div class="k">Creatina</div><div class="v">Vem da produção própria, da carne e do suplemento; vegano que treina precisa suplementar, em dose individual.</div></div><div class="ln"><div class="k">Cisto</div><div class="v">Cavidade com epitélio e líquido; na maioria das vezes, silenciosa.</div></div><div class="ln"><div class="k">Cisto simples</div><div class="v">O mais comum; achado de exame; ecografia uma vez por ano.</div></div><div class="ln"><div class="k">Bosniak</div><div class="v">I e II: acompanhe. A partir do IIF: encaminhe ao especialista.</div></div><div class="ln"><div class="k">Recessiva</div><div class="v">Rara e grave; cistos nos ductos coletores; recém-nascido; 1 em 4 de repetir no próximo filho.</div></div><div class="ln"><div class="k">Dominante</div><div class="v">Comum e sistêmica; cistos em todo o néfron dos dois rins; insuficiência renal por volta dos 60 anos.</div></div><div class="ln"><div class="k">Diagnóstico</div><div class="v">Número de cistos conforme a idade, mais história familiar; teste genético existe, mas não é usual.</div></div><div class="ln"><div class="k">Tratamento</div><div class="v">Sintomas, pressão, água acima de 3 L, café até 200 mL e evitar impacto; tolvaptana a caminho.</div></div><div class="ln"><div class="k">Rim em esponja</div><div class="v">Coletores da medula; facilita cálculos; alcalinizar a urina.</div></div><div class="ln"><div class="k">Nefronoftise</div><div class="v">Criança, recessiva, perda de sal; basta saber que existe.</div></div><div class="ln"><div class="k">Adquirida</div><div class="v">Diálise de muitos anos; risco de câncer; fazer exame de imagem.</div></div><div class="ln"><div class="k">Angiomiolipoma</div><div class="v">Gordura, músculo e vaso; preocupa se pobre em gordura, maior que 6 cm ou crescendo rápido.</div></div></div><div class="box red"><div class="kick"><span class="dot"></span>Erros comuns</div><ul><li><b>Achar que toda dor lombar é cálculo.</b> No policístico, ela vem da distensão do rim pelos cistos.</li><li><b>Achar que hematúria é sempre litíase.</b> Pense em cisto que rompeu, infecção, angiomiolipoma e tumor maligno.</li><li><b>Encaminhar todo cisto da ecografia.</b> Bosniak I e II se acompanham na atenção básica, uma vez por ano.</li><li><b>Deixar um IIF só em observação.</b> A partir dele, o encaminhamento é obrigatório.</li><li><b>Mandar o policístico esperar a consulta sem orientação.</b> Água, café limitado e menos impacto começam no primeiro atendimento.</li><li><b>Ver a policística dominante como doença só do rim.</b> É sistêmica: fígado, pâncreas, valvas e cérebro; investigue aneurisma cerebral.</li><li><b>Confundir recessiva com dominante.</b> Recessiva: rara, recém-nascido, coletores. Dominante: comum, adulto, todo o néfron.</li><li><b>Tratar cistite simples com quinolona.</b> Ela fica para infecções graves, como a pielonefrite.</li></ul></div><h4>Mapa das doenças císticas</h4><div class="grid"><div class="card"><span class="tag">Hereditárias (genéticas)</span><ul><li><b>Policística autossômica dominante:</b> comum. Cistos em qualquer parte do néfron, nos dois rins; aparecem entre 30 e 40 anos.</li><li><b>Policística autossômica recessiva:</b> rara e grave. Cistos nos ductos coletores; já no recém-nascido.</li><li><b>Nefronoftise:</b> rara, da infância, recessiva. Basta saber que existe.</li></ul></div><div class="card"><span class="tag">Não hereditárias</span><ul><li><b>Cisto simples:</b> a mais comum. Adulto, achado de exame; acompanhar pela classificação de Bosniak.</li><li><b>Rim em esponja medular:</b> defeito do desenvolvimento nos coletores da medula; facilita cálculos.</li><li><b>Doença cística adquirida:</b> paciente em diálise há muitos anos; maior risco de virar câncer.</li></ul></div></div><h4>Palavras da aula em linguagem simples</h4><div class="linhas termos"><div class="ln"><div class="k">Acidose tubular renal</div><div class="v">O túbulo do rim não consegue manter o equilíbrio ácido do sangue, que fica ácido demais.</div></div><div class="ln"><div class="k">Alcalinizar a urina</div><div class="v">Deixar a urina menos ácida, o que dificulta a formação de alguns cálculos.</div></div><div class="ln"><div class="k">Aneurisma</div><div class="v">Dilatação na parede de uma artéria, que pode romper e sangrar.</div></div><div class="ln"><div class="k">Angiomiolipoma</div><div class="v">Tumor benigno do rim feito de gordura, músculo e vasos; também chamado hamartoma.</div></div><div class="ln"><div class="k">CISOP</div><div class="v">Consórcio Intermunicipal de Saúde do Oeste do Paraná, sediado em Cascavel.</div></div><div class="ln"><div class="k">Hematúria</div><div class="v">Sangue na urina: macroscópica (visível) ou microscópica (só no exame).</div></div><div class="ln"><div class="k">Hemi-hipertrofia</div><div class="v">Um lado do corpo mais desenvolvido do que o outro.</div></div><div class="ln"><div class="k">KDIGO</div><div class="v">Grupo internacional que publica as diretrizes que norteiam as condutas em nefrologia.</div></div><div class="ln"><div class="k">Mácula densa</div><div class="v">Grupo de células do túbulo que “sente” o sal e regula a pressão pelo sistema renina-angiotensina-aldosterona.</div></div><div class="ln"><div class="k">Marsupialização</div><div class="v">Cirurgia do urologista que abre o cisto e o deixa drenar.</div></div><div class="ln"><div class="k">Nefropatia perdedora de sal</div><div class="v">Rim que perde sal demais pela urina.</div></div><div class="ln"><div class="k">Oligoidrâmnio</div><div class="v">Pouco líquido amniótico durante a gestação.</div></div><div class="ln"><div class="k">Parênquima renal</div><div class="v">O tecido que faz o trabalho do rim: córtex e medula.</div></div><div class="ln"><div class="k">Policistina</div><div class="v">Proteína que recebe sinais de fora da célula e os leva para dentro; alterada na policística.</div></div><div class="ln"><div class="k">Polidipsia</div><div class="v">Beber água em excesso.</div></div><div class="ln"><div class="k">Ptose palpebral</div><div class="v">Pálpebra caída.</div></div><div class="ln"><div class="k">Tolvaptana</div><div class="v">Remédio que bloqueia o hormônio antidiurético e reduz a formação de cistos; ainda não disponível no Brasil.</div></div><div class="ln"><div class="k">Unilocular</div><div class="v">Com uma única cavidade, sem divisões por dentro.</div></div><div class="ln"><div class="k">Uremia</div><div class="v">Excesso de ureia e de outras escórias no sangue, quando o rim falha.</div></div></div>$ap$, 'nefrologia/aula-2.pdf');

insert into public.questoes (id, materia_id, aula_id, ordem, enunciado, alternativas, correta, comentario, por_que_erradas, tema, prova, fonte, origem) values
  ('nf-t19-01', 'nefro', 'nefro-a2', 1, 'Mulher de 35 anos, hipertensa, com doença renal crônica em tratamento conservador, apresenta infecções urinárias de repetição. A tomografia mostra os dois rins aumentados, tomados por múltiplas imagens císticas. Qual o diagnóstico?',
   '["Doença cística renal adquirida", "Doença renal policística do adulto", "Cistos renais simples", "Rim esponja medular", "Rim multicístico displásico"]'::jsonb, 1,
   'Adulta jovem, hipertensa, com doença renal crônica e rins aumentados cheios de cistos — ''a tomografia cheia de bolinhas'', nas palavras da professora — é doença renal policística autossômica dominante. Hipertensão precoce, infecção de cisto ou urinária, dor lombar, hematúria e perda progressiva de função fazem parte da evolução.
Nota: questão adaptada da UFRJ 2021; a queixa de repetição estava inaudível na gravação e foi completada como infecção urinária, complicação típica da doença.',
   'A: a doença cística adquirida ocorre em quem já está em diálise, com rins pequenos — a paciente está em tratamento conservador.
C: cistos simples são poucos, não substituem o parênquima e não causam DRC nem hipertensão.
D: o rim esponja medular dilata os ductos coletores da medula, com nefrocalcinose, sem cistos corticais múltiplos nem rins aumentados.
E: o rim multicístico displásico é unilateral, congênito e diagnosticado na infância.',
   'Doenças císticas e vasculares renais', 'p2-t19', 'P2 T19 · nº 1', 'professor'),
  ('nf-t19-02', 'nefro', null, 2, 'Gestante de 30 anos, secundigesta, sem abortos prévios, teve 2 episódios de bacteriúria assintomática no primeiro trimestre. No segundo trimestre, comparece ao pronto atendimento com febre, dor lombar à direita, PA 90×50 mmHg, pulso de 124 bpm, temperatura de 38,7 °C e confusão mental. Qual a conduta mais adequada?',
   '["Ciprofloxacino via oral e retorno em 72 horas", "Internação, estabilização hemodinâmica e antibiótico endovenoso para o quadro séptico; após o tratamento, acompanhamento e prevenção de novos episódios, com urocultura de controle e profilaxia até o fim da gestação", "Cefalexina via oral em regime ambulatorial", "Aguardar o resultado da urocultura antes de iniciar o antibiótico", "Antibiótico via oral e repouso domiciliar"]'::jsonb, 1,
   'É pielonefrite com sepse na gestação: febre, dor lombar, hipotensão, taquicardia e confusão mental. Conduta: internação, ressuscitação volêmica e antibiótico endovenoso imediato. Depois do quadro agudo, a gestante com bacteriúria de repetição e pielonefrite precisa de urocultura de controle e profilaxia antibiótica até o fim da gestação, porque a chance de recorrência é alta. A professora resumiu: ''nada de dar quinolona, cefalosporina oral e deixar a paciente morrer''.
Nota: questão adaptada de prova de residência de Pernambuco.',
   'A: quinolona é contraindicada na gestação, e sepse não se trata por via oral.
C: via oral ambulatorial numa paciente séptica é conduta insegura.
D: na sepse o antibiótico entra na primeira hora — colhe-se a urocultura, mas não se espera o resultado.
E: paciente hipotensa e confusa não vai para casa.',
   'Infecção urinária', 'p2-t19', 'P2 T19 · nº 2', 'professor'),
  ('nf-t19-03', 'nefro', null, 3, 'Homem de 45 anos, diabético recente, refere história familiar de doença renal crônica dialítica; pais e irmãos também são diabéticos. Está assintomático e sem alterações no exame físico. Exames: creatinina 0,6 mg/dL, ritmo de filtração glomerular de 141 mL/min e ultrassonografia com discreto aumento das dimensões de ambos os rins. Entre os exames abaixo, qual é o mais importante no momento?',
   '["Albuminúria em amostra isolada e exame parcial de urina", "Biópsia renal", "Cintilografia renal com DTPA", "Dosagem de cistatina C", "Angiotomografia das artérias renais"]'::jsonb, 0,
   'TFG de 141 com rins aumentados num diabético é HIPERFILTRAÇÃO — a fase mais inicial da doença renal do diabetes, antes de qualquer queda de função. Nesse momento, o que detecta a lesão é a albuminúria (relação albumina/creatinina em amostra isolada), junto com o exame de urina. Com a história familiar forte, o rastreio é ainda mais importante.
Notas: questão adaptada da USP Ribeirão Preto 2021. Na correção foram marcadas duas letras — albuminúria em amostra isolada e parcial de urina —, aqui juntas numa só alternativa. A transcrição dizia ''hipoalbuminúria''; o exame é a albuminúria.',
   'B: biópsia não se indica em diabético com quadro típico e sem albuminúria documentada.
C: a cintilografia avalia função relativa de cada rim, sem papel no rastreio da nefropatia diabética.
D: a cistatina C estima a TFG, que aqui já se sabe estar alta — não detecta a lesão inicial.
E: não há suspeita de estenose de artéria renal.',
   'Nefropatia diabética', 'p2-t19', 'P2 T19 · nº 3', 'professor'),
  ('nf-t19-04', 'nefro', null, 4, 'Paciente masculino, 38 anos, chega ao pronto-socorro com dor lombar à esquerda, súbita e de forte intensidade, e febre. Após analgesia e hidratação, você pede o exame de imagem disponível, a radiografia, que evidencia uma imagem arredondada radiopaca no trajeto urinário. Qual a hipótese mais provável?',
   '["Cálculo de ácido úrico", "Coágulo na pelve renal", "Cálculo de xantina", "Cálculo de oxalato de cálcio", "Tumor urotelial da pelve renal"]'::jsonb, 3,
   'Imagem radiopaca na radiografia simples, em crise de cólica renal, é cálculo com cálcio — e o oxalato de cálcio é o tipo mais comum, cerca de 70 a 80% dos cálculos. Os cálculos que contêm cálcio aparecem no raio X; os de ácido úrico não.',
   'A: ácido úrico é radiotransparente — não aparece na radiografia (só na tomografia).
B: coágulo não é radiopaco.
C: xantina também é radiotransparente, e é rara.
E: tumor urotelial não produz imagem arredondada radiopaca; aparece como falha de enchimento na urografia ou na tomografia.',
   'Litíase urinária', 'p2-t19', 'P2 T19 · nº 4', 'professor'),
  ('nf-t19-05', 'nefro', null, 5, 'Você trabalha em uma USF e atende paciente caucasiano de 54 anos com episódios de cefaleia occipital associados a PA elevada (180×120 mmHg) nos últimos 3 meses. Usa losartana 50 mg/dia há um mês, com discreta redução da pressão. Ao exame: bom estado geral, IMC 28, FC 62 bpm, PA 182×122 mmHg, sem outras alterações. Exames: creatinina 0,95 mg/dL, sódio 142, potássio 3,8, glicemia de jejum normal e exame de urina com pH normal e sem proteinúria. Qual a hipótese diagnóstica mais provável?',
   '["Hipertensão arterial primária", "Hiperaldosteronismo primário", "Feocromocitoma", "Estenose de artéria renal", "Síndrome de Cushing"]'::jsonb, 0,
   'Homem de 54 anos com sobrepeso, hipertensão grave mas ainda em dose baixa de um único anti-hipertensivo (losartana 50 mg), e nenhuma pista de causa secundária: potássio, sódio, creatinina e urina normais, sem taquicardia, sem paroxismos, sem sinais cushingoides. É hipertensão primária — o que falta é tratamento adequado (otimizar a dose e associar outra classe), não investigação. Faz contraponto com a questão da mulher de 28 anos com potássio baixo, em que a resposta é hiperaldosteronismo.
Nota: questão adaptada da USP Ribeirão Preto 2021.',
   'B: potássio de 3,8 e hipertensão que responde parcialmente a uma droga só não sugerem hiperaldosteronismo.
C: feocromocitoma dá crises paroxísticas com palpitação, sudorese e taquicardia — a FC é 62.
D: estenose de artéria renal costuma dar sopro abdominal, piora da creatinina com o BRA ou assimetria renal — nada disso aparece.
E: não há sinais de Cushing (obesidade central, estrias, fácies de lua cheia) nem hiperglicemia.',
   'Hipertensão arterial', 'p2-t19', 'P2 T19 · nº 5', 'professor'),
  ('nf-t19-06', 'nefro', null, 6, 'Baseado nas diretrizes brasileiras de doença renal crônica, classificamos como estágio 2 aquele que apresenta:',
   '["Ritmo de filtração igual ou maior que 90 mL/min, com albuminúria", "Ritmo de filtração entre 60 e 89 mL/min, assintomático", "Ritmo de filtração entre 30 e 59 mL/min, com anemia", "Ritmo de filtração entre 15 e 29 mL/min, com hipertensão e anemia", "Ritmo de filtração abaixo de 15 mL/min, em diálise"]'::jsonb, 1,
   'Estágio 2 é TFG entre 60 e 89 mL/min/1,73 m² — perda leve, em geral assintomática, e só é chamada de DRC quando há marcador de lesão renal (como albuminúria) por mais de 3 meses. Escala completa: G1 ≥ 90, G2 60–89, G3a 45–59, G3b 30–44, G4 15–29, G5 < 15. Faz par com a questão da T22 que pede o estágio 4.',
   'A: TFG ≥ 90 com marcador de lesão é o estágio 1.
C: 30 a 59 é o estágio 3.
D: 15 a 29 é o estágio 4.
E: abaixo de 15 é o estágio 5.',
   'Doença renal crônica', 'p2-t19', 'P2 T19 · nº 6', 'professor'),
  ('nf-t19-10', 'nefro', null, 7, 'São indicações de diálise de urgência, EXCETO:',
   '["Encefalopatia ou pericardite urêmica", "Hipercalemia de 5,8 mEq/L sem alterações no eletrocardiograma", "Hipervolemia não responsiva a diuréticos", "Acidose metabólica grave não responsiva às medidas clínicas", "Intoxicação exógena grave por substância dialisável"]'::jsonb, 1,
   'A explicação da professora: diálise de urgência é indicada na síndrome urêmica (encefalopatia, pericardite, coagulopatia), na hipervolemia que não responde a diurético, na hipercalemia GRAVE — acima de 6,5 mEq/L, refratária às medidas clínicas e com alteração no ECG —, na acidose metabólica refratária e na intoxicação por substância dialisável. Hipercalemia leve a moderada, sem alteração eletrocardiográfica, se trata clinicamente: gluconato de cálcio se houver alteração no ECG, insulina com glicose, beta-2 agonista, resina de troca e correção da causa.
Nota: a resposta era a letra B, mas o texto dela ficou inaudível na gravação (''o povo ficou em choque com a resposta''). A alternativa B foi reconstruída a partir da explicação da professora — por isso o selo é ''inferido''.',
   'A, C, D e E são indicações clássicas de diálise de urgência, exatamente as do quadro mostrado pela professora: síndrome urêmica, hipervolemia refratária, acidose refratária e intoxicação por substância dialisável.',
   'Doença renal crônica', 'p2-t19', 'P2 T19 · nº 10', 'inferido'),
  ('nf-t19-11', 'nefro', null, 8, 'Uma paciente de 50 anos é atendida com dor lombar bilateral e hematúria macroscópica. A ultrassonografia revelou a presença de imagens hiperecoicas, com sombra acústica posterior, de dimensões entre 1,5 e 2 cm em todos os cálices e na pelve, bilateralmente. O exame sumário de urina foi compatível com infecção do trato urinário (ITU). Nesse caso, espera-se encontrar:',
   '["Uma concentração de cistina urinária elevada", "Um pH urinário mais ácido, geralmente abaixo de 6,5", "A presença de Proteus mirabilis como agente causador da ITU", "A presença de oxalato e cálcio como principais constituintes do cálculo"]'::jsonb, 2,
   'Cálculos grandes ocupando todos os cálices e a pelve dos dois lados, com ITU, são cálculos coraliformes de estruvita (fosfato de amônio e magnésio) — o cálculo da infecção. Bactérias produtoras de urease, principalmente o Proteus mirabilis, quebram a ureia em amônia, alcalinizam a urina e fazem a estruvita precipitar e crescer rápido. Raciocínio da professora: que cálculo é esse? Estruvita. Quem faz? Proteus.
Fonte: UFRN 2021, com as 4 alternativas originais.',
   'A: cistinúria é doença genética de início na infância e juventude, sem relação com infecção.
B: a urina é ALCALINA (pH acima de 7) — a urease produz amônia.
D: oxalato de cálcio é o cálculo mais comum em geral, mas não é o coraliforme associado à infecção.',
   'Litíase urinária', 'p2-t19', 'P2 T19 · nº 11', 'professor'),
  ('nf-t19-12', 'nefro', 'nefro-a2', 9, 'Sobre infecção urinária, oclusão arterial renal progressiva, cateterismo, AVC e doença renal policística, assinale a correta:',
   '["A infecção urinária baixa não evolui para pielonefrite, mesmo quando não é tratada", "A oclusão progressiva da artéria renal por aterosclerose não causa hipertensão nem perda de função renal", "O contraste iodado usado no cateterismo não oferece risco renal ao paciente com doença renal crônica", "O AVC hemorrágico em paciente com doença renal policística não tem relação com a doença renal", "Na doença renal policística são sintomas comuns a dor lombar e a hematúria macroscópica, e o tratamento inicial é repouso"]'::jsonb, 4,
   'Dor lombar e hematúria macroscópica são queixas frequentes na doença renal policística — em geral por sangramento dentro de um cisto ou para a via urinária. O tratamento inicial é conservador: repouso, hidratação e analgesia (evitando anti-inflamatório). Observação da professora na correção: se depois de alguns dias não melhorar, encaminha-se para tratamento cirúrgico dos cistos (marsupialização).
Nota: as alternativas A a D foram reconstruídas, uma para cada tema que o enunciado cita.',
   'A: a infecção é ascendente — cistite mal tratada pode evoluir para pielonefrite.
B: a estenose aterosclerótica da artéria renal causa hipertensão renovascular e nefropatia isquêmica, com perda de função.
C: o contraste iodado pode causar lesão renal aguda, e o risco é maior justamente em quem já tem DRC.
D: a doença renal policística se associa a aneurismas intracranianos — a hemorragia pode ser consequência deles.',
   'Doenças císticas e vasculares renais', 'p2-t19', 'P2 T19 · nº 12', 'professor'),
  ('nf-t19-13', 'nefro', null, 10, 'São considerados fatores de piora para a progressão da doença renal crônica:',
   '["Infecção do trato urinário", "Hipertensão arterial não controlada", "Diabetes", "Retenção urinária", "Todas as acima"]'::jsonb, 4,
   'Todos aceleram a perda de função renal: a hipertensão não controlada e o diabetes lesam os glomérulos de forma contínua; a infecção urinária (principalmente a pielonefrite) inflama e cicatriza o parênquima; e a retenção urinária aumenta a pressão retrógrada sobre os rins (uropatia obstrutiva). Outros fatores que a prova pode trazer: proteinúria, tabagismo, dislipidemia, nefrotóxicos (anti-inflamatórios, contraste) e desidratação.',
   'A, B, C e D estão todas corretas isoladamente — por isso a resposta é ''todas as acima''.',
   'Doença renal crônica', 'p2-t19', 'P2 T19 · nº 13', 'professor'),
  ('nf-t19-14', 'nefro', null, 11, 'Analise as afirmativas e assinale a alternativa que contém apenas as corretas:
I. A pré-eclâmpsia aparece apenas no último mês de gestação.
II. A doença renal policística pode levar à insuficiência renal após a 6ª década de vida.
III. A nefropatia diabética é a primeira causa de insuficiência renal no Brasil.
IV. O principal agente da infecção do trato urinário é a Escherichia coli.
V. Na pielonefrite não há casos em que o tratamento possa ser feito ambulatorialmente.',
   '["I e II", "II e IV", "II, IV e V", "III e IV", "I, III e V"]'::jsonb, 1,
   'I — falsa: a pré-eclâmpsia surge a partir da 20ª semana, não só no último mês.
II — verdadeira: na doença renal policística a função cai ao longo de décadas, e a insuficiência renal costuma chegar por volta da 5ª–6ª década.
III — falsa: pelo censo da Sociedade Brasileira de Nefrologia, a hipertensão aparece à frente do diabetes como causa de doença renal em diálise.
IV — verdadeira: a E. coli responde por cerca de 80% das ITUs.
V — falsa: pielonefrite sem sinais de gravidade, em paciente que tolera via oral, pode ser tratada ambulatorialmente.
Notas: a professora avisou que esta questão apareceu na prova do semestre anterior com resposta diferente. O item I estava inaudível na gravação (''o que aparece no último mês de gestação'') e foi reconstruído.',
   'A: inclui a I, que é falsa.
C: inclui a V, que é falsa.
D: inclui a III, que é falsa, e deixa de fora a II.
E: reúne só as falsas.',
   'Doença renal crônica', 'p2-t19', 'P2 T19 · nº 14', 'professor'),
  ('nf-t22-01', 'nefro', null, 12, 'São indicações de diálise de urgência na doença renal crônica:',
   '["Anemia, hiperfosfatemia e prurido urêmico", "Creatinina acima de 4 mg/dL, mesmo em paciente assintomático", "Edema refratário a diuréticos, hipercalemia e encefalopatia urêmica", "Acidose metabólica compensada, hipertensão controlada e noctúria", "Hiperuricemia assintomática, hipocalcemia e osteodistrofia renal"]'::jsonb, 2,
   'Diálise de urgência é indicada quando uma complicação ameaça a vida e não responde ao tratamento clínico: hipervolemia refratária a diuréticos (com risco de edema agudo de pulmão), hipercalemia, acidose metabólica grave e uremia sintomática — encefalopatia, pericardite e sangramento urêmico. O mnemônico AEIOU ajuda: Acidose, Eletrólitos (potássio), Intoxicações, Overload (sobrecarga de volume) e Uremia.',
   'A: anemia, hiperfosfatemia e prurido são complicações crônicas, tratadas com eritropoetina, quelante de fósforo e ajuste de diálise programada.
B: um valor de creatinina, sozinho, não indica diálise — decide-se pela clínica e pela TFG.
D: acidose compensada, hipertensão controlada e noctúria não configuram urgência.
E: hiperuricemia assintomática, hipocalcemia e osteodistrofia são manejadas clinicamente.',
   'Doença renal crônica', 'p2-t22', 'P2 T22 · nº 1', 'unica'),
  ('nf-t22-02', 'nefro', null, 13, 'Baseado na diretriz de doença renal crônica da Sociedade Brasileira de Nefrologia, classificamos como estágio 4 de doença renal crônica:',
   '["Ritmo de filtração entre 60 e 89 mL/min, com hipertensão e anemia", "Ritmo de filtração entre 45 e 59 mL/min, com hipertensão e anemia", "Ritmo de filtração entre 30 e 44 mL/min, com hipertensão e anemia", "Ritmo de filtração entre 15 e 29 mL/min, com hipertensão e anemia", "Ritmo de filtração abaixo de 15 mL/min, com indicação de terapia renal substitutiva"]'::jsonb, 3,
   'O estadiamento da DRC é feito pela taxa de filtração glomerular (em mL/min/1,73 m²): G1 ≥ 90, G2 60–89, G3a 45–59, G3b 30–44, G4 15–29 e G5 < 15. Soma-se a categoria de albuminúria (A1, A2, A3). Hipertensão e anemia são complicações comuns a partir dos estágios 3 e 4, mas quem define o estágio é só a TFG — por isso aparecem em todas as alternativas.',
   'A: 60–89 é o estágio 2.
B: 45–59 é o estágio 3a.
C: 30–44 é o estágio 3b.
E: abaixo de 15 é o estágio 5, a falência renal.',
   'Doença renal crônica', 'p2-t22', 'P2 T22 · nº 2', 'unica'),
  ('nf-t22-03', 'nefro', 'nefro-a1', 14, 'Qual das equações abaixo corresponde à fórmula de Cockcroft & Gault para estimativa da depuração de creatinina?',
   '["ClCr = [(140 − idade) × peso] / (72 × creatinina); no sexo masculino, multiplicar por 0,85", "ClCr = [(140 − idade) × peso] / (72 × creatinina); no sexo feminino, multiplicar por 0,85", "ClCr = [(140 + idade) × peso] / (72 × creatinina); no sexo feminino, multiplicar por 0,85", "ClCr = (72 × creatinina) / [(140 − idade) × peso]; no sexo feminino, multiplicar por 0,85", "ClCr = [(140 − idade) × peso] / (72 × creatinina); no sexo feminino, multiplicar por 1,15"]'::jsonb, 1,
   'Dá para montar a fórmula pela lógica: a idade reduz o clearance (140 − idade); o peso em kg aumenta, porque acompanha a massa muscular que produz creatinina; a creatinina sérica vai no denominador, multiplicada por 72; e a mulher, com menos massa muscular, multiplica o resultado por 0,85. O resultado sai em mL/min, sem correção para a superfície corporal, e superestima a função em obesos e edemaciados.',
   'A: o fator 0,85 é da mulher, não do homem.
C: somar a idade faria o clearance subir com o envelhecimento — o contrário do que acontece.
D: a fração está invertida.
E: o fator da mulher reduz o valor (0,85); não existe 1,15 nesta fórmula.',
   'Função renal', 'p2-t22', 'P2 T22 · nº 3', 'unica'),
  ('nf-t22-04', 'nefro', null, 15, 'Em relação à litíase urinária, é INCORRETO afirmar:',
   '["Pode ocorrer tanto em adultos quanto em crianças", "São fatores litogênicos: condição do clima, profissão e tipo de alimentação", "O citrato mostrou-se eficaz na prevenção e no crescimento do cálculo", "O cálculo de ácido úrico pode ser evitado com a restrição da dieta proteica", "Os pacientes que têm cálculo de cálcio devem restringir leite e derivados"]'::jsonb, 4,
   'Restringir cálcio AUMENTA a litíase: sem cálcio no intestino para se ligar ao oxalato da dieta, sobra oxalato livre, que é absorvido e sai na urina (hiperoxalúria), formando mais cálculos de oxalato de cálcio. A orientação correta para quem forma cálculo de cálcio é manter a ingestão normal de cálcio (cerca de 1.000 a 1.200 mg/dia), restringir sódio e proteína animal e aumentar a ingestão de líquidos.
Apareceu de novo na P2 da T19 (nº7), com a mesma resposta — a professora repete essa questão.',
   'A, B, C e D são verdadeiras:
A: a litíase acomete todas as idades.
B: clima quente e profissões com calor ou pouca ingestão de água desidratam; dieta rica em sal e proteína animal é litogênica.
C: o citrato forma complexo solúvel com o cálcio e inibe a cristalização — o citrato de potássio é usado na prevenção.
D: proteína animal traz purinas e acidifica a urina, favorecendo o ácido úrico; restringi-la ajuda, junto com a alcalinização urinária.',
   'Litíase urinária', 'p2-t22', 'P2 T22 · nº 4', 'professor'),
  ('nf-t22-05', 'nefro', null, 16, 'Paciente branca, 28 anos, apresenta hipertensão arterial grau 2 de início recente, refere ter avó de 79 anos com hipertensão arterial, sem outros familiares com a doença. Exames revelam colesterol normal, glicemia de 86, ureia de 28, creatinina de 0,69 mg/dL, potássio sérico de 3 e exame parcial de urina normal. Ultrassom com rins de aspecto normal, sendo o direito medindo 11,2 cm e o esquerdo 11,4 cm. Considerando esses dados, pode-se afirmar que a etiologia mais provável da hipertensão é:',
   '["Hiperaldosteronismo primário", "Hipertensão arterial primária", "Nefrite aguda", "Estenose da artéria renal unilateral", "Glomerulonefrite crônica"]'::jsonb, 0,
   'Hipertensão com hipocalemia espontânea (K 3,0, sem diurético) em paciente jovem é hiperaldosteronismo primário até prova em contrário — é a causa endócrina mais comum de hipertensão secundária. O excesso de aldosterona retém sódio e elimina potássio. O rastreio é a relação aldosterona/renina (aldosterona alta com renina suprimida). Função renal e urina normais e rins de tamanho normal e simétrico afastam as causas renais parenquimatosas.
Apareceu de novo na P2 da T19 (nº9), com a mesma resposta. Na transcrição daquela turma o potássio aparece como ''okay'' (trecho pouco audível) — lembre que o hiperaldosteronismo primário também pode ter potássio normal; a hipocalemia reforça, mas não é obrigatória.',
   'B: hipocalemia espontânea não faz parte da hipertensão primária, e início recente de HAS grau 2 aos 28 anos pede investigação.
C: nefrite aguda daria hematúria, proteinúria e edema — a urina está normal.
D: é a concorrente: também pode dar hipocalemia (hiperaldosteronismo secundário), mas a renina estaria alta, e a estenose unilateral significativa costuma deixar o rim afetado menor (diferença acima de 1,5 cm) e produzir sopro abdominal. Rins simétricos e sem sopro favorecem a causa adrenal.
E: glomerulonefrite crônica cursa com rins pequenos, alteração no exame de urina e creatinina elevada.',
   'Hipertensão arterial', 'p2-t22', 'P2 T22 · nº 5', 'professor'),
  ('nf-t22-06', 'nefro', null, 17, 'Uma mulher na 14ª semana de gestação vem para a consulta na UBS, assintomática. Traz exames colhidos de rotina com urocultura positiva. Dentre as opções abaixo, a melhor conduta é:',
   '["Não tratar, pois a paciente é assintomática, e repetir a urocultura no 3º trimestre", "Ciprofloxacino por 7 dias", "Doxiciclina por 7 dias", "Internação para antibiótico endovenoso", "Cefalexina ou amoxicilina"]'::jsonb, 4,
   'A gestação é a grande exceção à regra de não tratar bacteriúria assintomática. Sem tratamento, 20 a 40% das gestantes evoluem para pielonefrite, com risco de parto prematuro e baixo peso ao nascer. Os betalactâmicos (cefalexina, amoxicilina) são seguros na gravidez; o ideal é guiar pelo antibiograma e repetir a urocultura de controle após o tratamento.',
   'A: é a pegadinha — na gestante a bacteriúria assintomática SEMPRE se trata.
B: quinolonas são contraindicadas na gestação (lesão de cartilagem fetal).
C: tetraciclinas são contraindicadas (depósito em dentes e ossos do feto).
D: sem sintomas, o tratamento é oral e ambulatorial.',
   'Infecção urinária', 'p2-t22', 'P2 T22 · nº 6', 'unica'),
  ('nf-t22-07', 'nefro', null, 18, 'Sobre infecção urinária, assinale a correta:',
   '["O Staphylococcus saprophyticus é o agente mais comum da cistite", "A infecção urinária baixa, se não tratada corretamente, pode evoluir para pielonefrite aguda", "A bacteriúria assintomática deve ser tratada em todo adulto", "A urocultura é obrigatória antes de tratar toda cistite não complicada em mulher jovem", "Homens têm mais infecção urinária que mulheres em todas as faixas etárias"]'::jsonb, 1,
   'A infecção urinária é, na imensa maioria, ascendente: a bactéria da flora perineal sobe pela uretra até a bexiga (cistite) e, se não for controlada, segue pelo ureter até a pelve e o parênquima renal (pielonefrite). Por isso a cistite mal tratada pode evoluir para pielonefrite aguda.',
   'A: o agente mais comum é a Escherichia coli (cerca de 80%); o S. saprophyticus é o segundo em mulheres jovens.
C: bacteriúria assintomática só se trata em gestantes e antes de procedimento urológico invasivo.
D: cistite não complicada em mulher jovem é tratada de forma empírica, sem urocultura.
E: a mulher tem mais ITU pela uretra curta; a exceção é o primeiro ano de vida.',
   'Infecção urinária', 'p2-t22', 'P2 T22 · nº 7', 'unica'),
  ('nf-t22-08', 'nefro', null, 19, 'Sobre as doenças vasculares e as doenças císticas, analise as afirmativas e marque V ou F:
( ) Hipertensão ocorre em mais de 50% dos pacientes com doença renal policística dominante do adulto antes da perda da função e parece ser um marcador de doença mais grave.
( ) Os cistos renais simples são achados raros em exames de imagem.
( ) Os cistos renais adquiridos são frequentes em pacientes renais crônicos em diálise.
( ) O tratamento das embolias renais agudas pode ser feito ambulatorialmente sem urgência.',
   '["V-V-V-F", "V-F-V-F", "V-V-V-V", "F-F-F-F", "F-V-F-V"]'::jsonb, 1,
   '1ª — V: na doença renal policística autossômica dominante, a hipertensão aparece cedo, em mais da metade dos pacientes antes de a função renal cair, e se associa a doença mais grave.
2ª — F: cisto renal simples é achado COMUM; mais da metade das pessoas acima de 50 anos tem pelo menos um.
3ª — V: a doença cística adquirida é frequente em quem está em diálise, aumenta com o tempo de diálise e traz risco de carcinoma de células renais.
4ª — F: embolia renal aguda é urgência — anticoagulação e avaliação de revascularização para salvar parênquima.',
   'A: considera verdadeira a 2ª afirmativa.
C: considera verdadeiras a 2ª e a 4ª.
D: marca todas como falsas.
E: inverte todas.',
   'Doenças císticas e vasculares renais', 'p2-t22', 'P2 T22 · nº 8', 'professor'),
  ('nf-t22-09', 'nefro', null, 20, 'Em relação à nefropatia diabética:',
   '["A microalbuminúria é um preditor importante e fidedigno da doença renal no paciente diabético", "O rastreio deve começar apenas quando a creatinina sérica se eleva", "IECA e BRA são contraindicados na presença de albuminúria", "A glicemia de jejum é o melhor marcador de lesão renal no diabético", "O controle da pressão arterial não altera a progressão da nefropatia"]'::jsonb, 0,
   'A albuminúria de 30 a 300 mg/g na relação albumina/creatinina é o marcador mais precoce da nefropatia diabética: aparece antes da queda da TFG e prediz tanto a progressão renal quanto o risco cardiovascular. O rastreio é anual — no DM2 desde o diagnóstico, no DM1 a partir de 5 anos de doença. Na nomenclatura atual (KDIGO), a ''microalbuminúria'' é chamada de albuminúria moderadamente aumentada (A2).',
   'B: a creatinina sobe tarde, quando já houve perda importante de função — o rastreio é pela albuminúria.
C: IECA e BRA são justamente indicados na albuminúria: reduzem a proteinúria e retardam a progressão.
D: a glicemia mede o controle do diabetes, não a lesão renal.
E: o controle pressórico é uma das medidas que mais retardam a progressão.',
   'Nefropatia diabética', 'p2-t22', 'P2 T22 · nº 9', 'unica'),
  ('nf-t22-10', 'nefro', 'nefro-a2', 21, 'Durante a consulta de rotina com seu nefrologista, um paciente nefropata recebeu a recomendação de que fosse investigada a possibilidade de aneurisma intracraniano, devido ao relato do falecimento de dois familiares de 1º grau, também nefropatas, por hemorragia cerebral subaracnóidea. A provável doença renal desse paciente é:',
   '["Doença renal policística", "Síndrome hemolítico-urêmica", "Síndrome de Alport", "Nefropatia por IgA", "Nefropatia diabética"]'::jsonb, 0,
   'A doença renal policística autossômica dominante é a nefropatia hereditária associada a aneurismas intracranianos: cerca de 10% dos pacientes os têm, e a proporção chega a 20% quando há história familiar de aneurisma ou hemorragia subaracnóidea — situação em que o rastreio com angiorressonância é indicado. Doença renal que passa de pais para filhos + morte de parentes por hemorragia cerebral = policística.',
   'B: a síndrome hemolítico-urêmica é microangiopatia trombótica (anemia hemolítica, plaquetopenia e lesão renal aguda), sem aneurismas.
C: a síndrome de Alport associa nefropatia a surdez neurossensorial e alterações oculares.
D: a nefropatia por IgA dá hematúria após infecção respiratória e não se associa a aneurisma.
E: a nefropatia diabética não tem relação com aneurisma intracraniano.',
   'Doenças císticas e vasculares renais', 'p2-t22', 'P2 T22 · nº 10', 'unica'),
  ('nf-t22-11', 'nefro', null, 22, 'A hipertensão arterial sistêmica tem alta prevalência e é um dos principais fatores de risco para doenças cardíacas e renais. Ciente disso, leia as afirmações e assinale as corretas:
I. A importância do controle do peso, pois a obesidade geral e abdominal está associada ao aumento do risco de hipertensão.
II. A importância de uma dieta saudável — várias propostas de dieta, sabidamente, contribuem para o controle pressórico e a melhora da saúde.
III. Atividade física como fator adicional, sem necessidade de frequência e tempo de duração.
IV. A facilidade de acesso à medicação anti-hipertensiva para todos os graus de hipertensão, por estar disponível na rede pública.',
   '["I, II e III", "I, II e IV", "II, III e IV", "I e II", "II e III"]'::jsonb, 1,
   'I — verdadeira: a obesidade, principalmente abdominal, aumenta o risco de hipertensão, e perder peso reduz a pressão.
II — verdadeira: dietas como DASH e mediterrânea, com menos sódio e mais potássio, ajudam no controle pressórico.
III — falsa: a atividade física TEM recomendação de frequência e duração — pelo menos 150 minutos por semana de intensidade moderada (por exemplo, 30 minutos, 5 vezes por semana).
IV — considerada verdadeira pelo gabarito: os anti-hipertensivos básicos são distribuídos gratuitamente na rede pública. Ressalva: é discutível, porque no estágio 1 de baixo risco a conduta inicial é só mudança de estilo de vida. Vale o gabarito até o professor dizer o contrário.',
   'A, C e E: incluem a III, que é falsa.
D: deixa de fora a IV, considerada correta pelo gabarito.',
   'Hipertensão arterial', 'p2-t22', 'P2 T22 · nº 11', 'professor'),
  ('nf-t27-01', 'nefro', null, 23, 'Jovem de 17 anos busca atendimento após ter iniciado diarreia sanguinolenta há 7 dias. Você é o médico da UBS e inicia a investigação clínica e com exames complementares, que revelam anemia de etiologia hemolítica, trombocitopenia e elevação da ureia e da creatinina. Nesse caso, a sua hipótese diagnóstica mais provável é:',
   '["Púrpura trombocitopênica trombótica", "Glomerulonefrite pós-estreptocócica", "Coagulação intravascular disseminada", "Síndrome hemolítico-urêmica", "Nefropatia por IgA"]'::jsonb, 3,
   'A síndrome hemolítico-urêmica é a tríade anemia hemolítica microangiopática + plaquetopenia + lesão renal aguda. Quando vem precedida de diarreia sanguinolenta, a causa é a Escherichia coli produtora de toxina Shiga (O157:H7): a toxina lesa o endotélio dos capilares glomerulares, formam-se microtrombos, as hemácias se fragmentam (esquizócitos) e as plaquetas são consumidas. É a principal causa de lesão renal aguda na infância.
Apareceu também na P2 da T19 (nº8), com uma mulher de 22 anos. Na correção daquela turma a professora citou Shigella e Salmonella como agentes; a causa clássica da SHU típica é a E. coli O157:H7, junto com a Shigella dysenteriae tipo 1.',
   'A: a PTT é a grande concorrente — também é microangiopatia trombótica, mas predomina o quadro neurológico e a febre, com atividade da ADAMTS13 muito baixa, e não vem precedida de diarreia.
B: a glomerulonefrite pós-estreptocócica dá hematúria, edema e hipertensão após faringite ou impetigo, sem hemólise nem plaquetopenia.
C: a CIVD alteraria o coagulograma (TP e TTPA alargados, fibrinogênio baixo), o que não é o padrão da SHU.
E: a nefropatia por IgA dá hematúria após infecção respiratória, sem hemólise nem plaquetopenia.',
   'Doenças císticas e vasculares renais', 'p2-t27', 'P2 T27 · nº 1', 'unica'),
  ('nf-t27-02', 'nefro', null, 24, 'Paciente de 65 anos, hipertenso há 20 anos, apresenta edema de membros inferiores, fadiga e oligúria. Exames demonstram creatinina sérica de 4,5 mg/dL e proteinúria de 2 gramas em 24 horas. Qual o diagnóstico mais provável?',
   '["Lesão renal aguda pré-renal", "Síndrome nefrótica por lesão mínima", "Glomerulonefrite rapidamente progressiva", "Doença renal crônica de causa hipertensiva (nefroesclerose hipertensiva)", "Necrose tubular aguda"]'::jsonb, 3,
   'Hipertensão de longa data, proteinúria subnefrótica (abaixo de 3,5 g/24h) e creatinina elevada com sintomas de uremia e hipervolemia compõem o quadro da nefroesclerose hipertensiva: a pressão alta crônica espessa as arteríolas renais, os glomérulos isquemiam e esclerosam, e a função cai de forma lenta e progressiva. É, junto com o diabetes, a principal causa de doença renal crônica.
Correção da transcrição: estava escrito ''doença renal crônica de cálcio hipertensiva'' — o correto é ''de causa hipertensiva''.',
   'A: a lesão pré-renal é aguda, com causa desencadeante (desidratação, hipotensão) e sem proteinúria dessa magnitude.
B: a lesão mínima dá proteinúria maciça (nefrótica) em paciente geralmente jovem e com função renal preservada.
C: a glomerulonefrite rapidamente progressiva perde função em dias a semanas, com hematúria e cilindros hemáticos.
E: a necrose tubular aguda vem após um insulto (isquemia, nefrotóxico), sem proteinúria significativa nem história de 20 anos.',
   'Doença renal crônica', 'p2-t27', 'P2 T27 · nº 2', 'unica'),
  ('nf-t27-03', 'nefro', null, 25, 'Sabe-se que a gravidez pode induzir hipertensão arterial em mulheres previamente normotensas ou agravar uma hipertensão preexistente. O aparecimento de hipertensão arterial, edema e proteinúria após a 20ª semana de gestação, na ausência de convulsão, em gestante previamente normotensa, denomina-se:',
   '["Hipertensão gestacional", "Hipertensão arterial crônica", "Pré-eclâmpsia", "Eclâmpsia", "Síndrome HELLP"]'::jsonb, 2,
   'Hipertensão que surge após a 20ª semana em gestante antes normotensa, acompanhada de proteinúria, é pré-eclâmpsia. Atualização que vale saber: o edema não faz mais parte do critério diagnóstico (é comum em gestações normais), e a proteinúria pode ser substituída por sinais de lesão de órgão-alvo — plaquetopenia, alteração hepática ou renal, sintomas neurológicos ou edema pulmonar.',
   'A: hipertensão gestacional é a que surge após 20 semanas SEM proteinúria nem lesão de órgão-alvo.
B: hipertensão crônica é a que já existia antes da gestação ou aparece antes da 20ª semana.
D: eclâmpsia exige convulsão — o enunciado diz que não houve.
E: a síndrome HELLP exige hemólise, elevação de enzimas hepáticas e plaquetopenia.',
   'Hipertensão arterial', 'p2-t27', 'P2 T27 · nº 3', 'unica'),
  ('nf-t27-04', 'nefro', null, 26, 'As opções a seguir apresentam condições que predispõem à ocorrência de nefrolitíase, à exceção de uma. Assinale-a:',
   '["Hipercalciúria", "Hiperuricosúria", "Alto volume urinário", "Hipocitratúria", "Hiperoxalúria"]'::jsonb, 2,
   'O alto volume urinário é justamente o principal fator de PROTEÇÃO contra cálculos: urina diluída mantém os solutos abaixo do ponto de supersaturação. A meta na prevenção é um volume urinário acima de 2 a 2,5 litros por dia. Todas as outras alternativas são os distúrbios metabólicos clássicos da litíase.',
   'A: a hipercalciúria é o distúrbio metabólico mais comum nos formadores de cálculo de cálcio.
B: a hiperuricosúria favorece cálculos de ácido úrico e também de oxalato de cálcio.
D: o citrato inibe a cristalização; pouco citrato na urina facilita o cálculo.
E: o excesso de oxalato forma cálculo de oxalato de cálcio, o tipo mais frequente.',
   'Litíase urinária', 'p2-t27', 'P2 T27 · nº 4', 'unica'),
  ('nf-t27-05', 'nefro', 'nefro-a1', 27, 'Para estimar a taxa de filtração glomerular à beira do leito, utiliza-se o clearance de creatinina calculado pela fórmula de Cockcroft-Gault. Qual dos seguintes parâmetros NÃO é utilizado nesse cálculo?',
   '["Idade", "Sódio sérico", "Peso", "Creatinina sérica", "Sexo"]'::jsonb, 1,
   'A fórmula é ClCr = [(140 − idade) × peso] / (72 × creatinina), multiplicada por 0,85 na mulher. Entram idade, peso, creatinina sérica e sexo — o sódio não participa. Faz par com a questão da T22 que pede a fórmula completa.',
   'A, C, D e E fazem parte da fórmula: a idade reduz o clearance (140 − idade), o peso o aumenta, a creatinina fica no denominador e o sexo feminino multiplica o resultado por 0,85.',
   'Função renal', 'p2-t27', 'P2 T27 · nº 5', 'unica'),
  ('nf-t27-06', 'nefro', null, 28, 'Julgue a afirmativa: A formação de cálculos de estruvita, frequentemente associados à infecção do trato urinário por bactérias produtoras de urease, ocorre principalmente em urina ácida e está relacionada à hipercalciúria idiopática.',
   '["Certo", "Errado"]'::jsonb, 1,
   'Só a primeira parte está certa. A estruvita (fosfato de amônio e magnésio) é o cálculo da infecção: bactérias produtoras de urease — Proteus, Klebsiella, Pseudomonas — quebram a ureia em amônia, que ALCALINIZA a urina (pH acima de 7), e é nesse meio alcalino que a estruvita precipita. Não tem relação com hipercalciúria. São os cálculos coraliformes, que crescem rápido e ocupam a pelve e os cálices; o tratamento exige remover todo o cálculo e erradicar a infecção.',
   'A: a afirmativa troca o pH (a estruvita forma-se em urina alcalina, não ácida) e a causa (infecção por bactéria produtora de urease, não hipercalciúria idiopática).',
   'Litíase urinária', 'p2-t27', 'P2 T27 · nº 6', 'professor'),
  ('nf-t27-07', 'nefro', null, 29, 'Em relação aos diuréticos, assinale a alternativa INCORRETA:',
   '["A furosemida inibe o cotransportador Na-K-2Cl no ramo ascendente espesso da alça de Henle", "Os tiazídicos atuam no túbulo contorcido distal e podem causar hipocalemia", "A acetazolamida inibe a anidrase carbônica no túbulo proximal", "A espironolactona é uma agonista da aldosterona", "Os diuréticos poupadores de potássio podem causar hipercalemia, principalmente na doença renal crônica"]'::jsonb, 3,
   'A espironolactona é ANTAGONISTA do receptor mineralocorticoide: bloqueia a aldosterona no túbulo coletor, reduzindo a reabsorção de sódio e a excreção de potássio — por isso é poupadora de potássio. Um agonista faria o contrário: reteria sódio e eliminaria potássio.',
   'A, B, C e E são verdadeiras:
A: a furosemida é o diurético de alça, o mais potente, e age no cotransportador Na-K-2Cl.
B: os tiazídicos agem no cotransportador Na-Cl do túbulo distal; ao aumentar a oferta de sódio ao coletor, aumentam a perda de potássio.
C: a acetazolamida inibe a anidrase carbônica no túbulo proximal e causa acidose metabólica leve.
E: espironolactona, amilorida e triantereno retêm potássio — risco maior quando a função renal está reduzida ou em associação com IECA/BRA.',
   'Diuréticos', 'p2-t27', 'P2 T27 · nº 7', 'unica'),
  ('nf-t27-08', 'nefro', 'nefro-a2', 30, 'Com relação à doença renal policística autossômica dominante, é INCORRETO afirmar:',
   '["É a doença renal hereditária mais comum", "Associa-se a aneurismas intracranianos", "Os cistos são caracteristicamente unilaterais", "Pode cursar com cistos hepáticos", "A hipertensão arterial é manifestação precoce e frequente"]'::jsonb, 2,
   'Na doença renal policística autossômica dominante os cistos são BILATERAIS: os dois rins aumentam de tamanho, tomados por múltiplos cistos que substituem o parênquima ao longo de décadas. Cistos renais unilaterais sugerem outro diagnóstico (displasia multicística, cisto simples). Faz par com as questões nº8 e nº10 da T22.',
   'A, B, D e E são verdadeiras:
A: é a doença renal hereditária mais frequente, causada por mutações em PKD1 ou PKD2.
B: cerca de 10% dos pacientes têm aneurisma intracraniano, mais ainda quando há história familiar de hemorragia subaracnóidea.
D: os cistos hepáticos são a manifestação extrarrenal mais comum.
E: a hipertensão aparece cedo, antes da perda de função, em mais da metade dos pacientes.',
   'Doenças císticas e vasculares renais', 'p2-t27', 'P2 T27 · nº 8', 'unica'),
  ('nf-t27-09', 'nefro', null, 31, 'A doença renal do diabetes é uma das principais causas de doença renal crônica terminal. Nesse contexto, todas as recomendações a seguir são importantes para o tratamento e a evolução, EXCETO uma. Assinale-a:',
   '["Controle glicêmico individualizado, com meta de HbA1c em torno de 7%", "O uso de inibidores do SGLT2 tem indicação nesses pacientes por suas várias ações, incluindo a vasodilatação da arteríola aferente", "Uso de IECA ou BRA em pacientes com albuminúria", "Controle da pressão arterial e da dislipidemia", "Cessação do tabagismo e restrição de sódio na dieta"]'::jsonb, 1,
   'O iSGLT2 TEM indicação na doença renal do diabetes — o erro está no mecanismo. Ao bloquear a reabsorção de sódio e glicose no túbulo proximal, chega mais sódio à mácula densa, que ativa o feedback tubuloglomerular e provoca VASOCONSTRIÇÃO da arteríola aferente: a pressão intraglomerular cai e a hiperfiltração diminui.
Comparação que a prova gosta de cobrar:
• iSGLT2 → contrai a AFERENTE (entrada do glomérulo).
• IECA/BRA → dilata a EFERENTE (saída do glomérulo).
Os dois reduzem a pressão dentro do glomérulo e, por isso, podem subir um pouco a creatinina no início — sinal de efeito, não de lesão.',
   'A, C, D e E são recomendações corretas:
A: o controle glicêmico retarda a progressão, com meta individualizada em torno de 7%.
C: IECA ou BRA reduzem a albuminúria e a progressão.
D: controlar pressão e lipídios reduz a progressão renal e o risco cardiovascular.
E: tabagismo acelera a perda de função, e o excesso de sódio anula parte do efeito do IECA/BRA.',
   'Nefropatia diabética', 'p2-t27', 'P2 T27 · nº 9', 'unica'),
  ('nf-t27-10', 'nefro', null, 32, 'Paciente de 62 anos, com hipertensão de longa data, vem ao ambulatório de clínica médica encaminhado pelo médico da UBS para adequar a medicação anti-hipertensiva. Você, acadêmico no estágio, é solicitado a medir a pressão do paciente, avaliar os exames complementares e classificar a hipertensão e a doença renal crônica, se houver. Pressão arterial 160/100 mmHg; pulso 96; ureia 76; creatinina 1,54; taxa de filtração glomerular 38 mL/min/1,73 m²; microalbuminúria isolada 125 mg/g.',
   '["Hipertensão grau 1; doença renal crônica estágio 3a A2", "Hipertensão grau 3; doença renal crônica estágio 3b A3", "Hipertensão grau 2; doença renal crônica estágio 4 A2", "Hipertensão grau 2; doença renal crônica estágio 3a A1", "Hipertensão grau 2; doença renal crônica estágio 3b A2"]'::jsonb, 4,
   'Três classificações numa questão só:
• Pressão: 160/100 está na faixa 160–179 / 100–109 mmHg → hipertensão grau 2 (grau 1 é 140–159 / 90–99; grau 3 é ≥ 180 / ≥ 110).
• TFG: 38 está entre 30 e 44 → estágio G3b (G3a é 45–59; G4 é 15–29).
• Albuminúria: 125 mg/g está entre 30 e 300 → A2 (A1 < 30; A3 > 300).
Faz par com a questão da T22 sobre o estágio 4.',
   'A: 160/100 não é grau 1, e TFG 38 não é 3a.
B: 160/100 não chega ao grau 3, e 125 mg/g não é A3.
C: TFG 38 não é estágio 4 (15–29).
D: TFG 38 não é 3a, e 125 mg/g não é A1.',
   'Doença renal crônica', 'p2-t27', 'P2 T27 · nº 10', 'unica');

insert into public.flashcards (id, aula_id, ordem, frente, verso) values
  ('nefro-a1-f01', 'nefro-a1', 1, 'Qual é a diurese normal de um adulto de 70 kg?', '2.100 a 2.800 mL em 24 horas, cerca de 30 a 40 mL por quilo.'),
  ('nefro-a1-f02', 'nefro-a1', 2, 'Qual é o limite da oligúria?', 'Diurese abaixo de 400 mL em 24 horas.'),
  ('nefro-a1-f03', 'nefro-a1', 3, 'O que é anúria, na definição da Dra. Vanessa?', 'Ausência de diurese: a pessoa não urina (0 mL em 24 horas).'),
  ('nefro-a1-f04', 'nefro-a1', 4, 'Qual é o limite da poliúria?', 'Diurese acima de 3.000 mL em 24 horas.'),
  ('nefro-a1-f05', 'nefro-a1', 5, 'Quais exames avaliam o glomérulo?', 'Ureia e creatinina no sangue, depuração de creatinina (taxa de filtração glomerular) e proteína na urina.'),
  ('nefro-a1-f06', 'nefro-a1', 6, 'Quais exames avaliam o túbulo?', 'O exame de urina: densidade, osmolaridade, sódio e potássio urinários.'),
  ('nefro-a1-f07', 'nefro-a1', 7, 'Qual é o caminho da ureia?', 'Proteínas → amônia (tóxica) → fígado, no ciclo da ureia → ureia → filtrada pelo rim e eliminada na urina.'),
  ('nefro-a1-f08', 'nefro-a1', 8, 'Qual é o valor normal da ureia no sangue?', '10 a 40 mg/dL.'),
  ('nefro-a1-f09', 'nefro-a1', 9, 'Ureia alta: em que pensar?', 'Entrada (muita proteína), saída (o rim elimina pouco) ou as duas coisas ao mesmo tempo.'),
  ('nefro-a1-f10', 'nefro-a1', 10, 'Dieta pobre em proteína é boa para o rim?', 'Não. Produz menos ureia, mas prejudica a imunidade, a cicatrização e a defesa contra infecções.'),
  ('nefro-a1-f11', 'nefro-a1', 11, 'Como o ácido úrico é eliminado?', '3/4 pelo rim e 1/4 pelo intestino. 90% do que é filtrado volta no túbulo proximal; só 10% sai na urina.'),
  ('nefro-a1-f12', 'nefro-a1', 12, 'O que faz o ácido úrico subir?', 'Álcool (inclusive cerveja), carnes e frutos do mar em excesso, síndrome de lise tumoral e insuficiência renal.'),
  ('nefro-a1-f13', 'nefro-a1', 13, 'Por que a creatinina é uma boa marcadora do rim?', 'Vem do músculo esquelético em produção constante, é livremente filtrada, não é reabsorvida e é pouco secretada.'),
  ('nefro-a1-f14', 'nefro-a1', 14, 'Qual é o valor normal da creatinina, na visão da professora?', 'Abaixo de 1,2 mg/dL, idealmente abaixo de 1,0. Nos laboratórios: 0,8 a 1,3.'),
  ('nefro-a1-f15', 'nefro-a1', 15, 'Como o corpo fabrica a creatina?', 'Rim: arginina + glicina viram ácido guanidinoacético → fígado: + metionina = creatina → músculo guarda como fosfocreatina.'),
  ('nefro-a1-f16', 'nefro-a1', 16, 'Ovo e leite aumentam a creatina?', 'Não: nenhum dos dois tem músculo esquelético. Carne vermelha, frango, peixe e porco têm creatina.'),
  ('nefro-a1-f17', 'nefro-a1', 17, 'Quem tem indicação real de suplementar creatina?', 'Veganos e vegetarianos, cuja dieta tem pouca ou nenhuma creatina.'),
  ('nefro-a1-f18', 'nefro-a1', 18, 'Duas pessoas saudáveis com creatininas diferentes: uma tem o rim pior?', 'Não necessariamente. A creatinina depende da massa muscular; para julgar o rim, use a taxa de filtração glomerular.'),
  ('nefro-a1-f19', 'nefro-a1', 19, 'Qual é o valor normal da taxa de filtração glomerular?', 'Acima de 90, ou “mais de 90% do rim funcionando”.'),
  ('nefro-a1-f20', 'nefro-a1', 20, 'Para que serve a cistatina C?', 'Estima a filtração sem depender da massa muscular. É mais eficaz e mais cara que a creatinina; útil nos casos duvidosos.'),
  ('nefro-a1-f21', 'nefro-a1', 21, 'Qual é a regra de ouro da aula 1?', 'Ureia e creatinina altas: ingestão alta, rim que não filtra, ou os dois.'),
  ('nefro-a2-f01', 'nefro-a2', 1, 'O que é um cisto renal?', 'Uma cavidade delimitada por epitélio e preenchida por líquido. Na maioria das vezes, não dá sintoma.'),
  ('nefro-a2-f02', 'nefro-a2', 2, 'Qual é a doença cística renal mais comum?', 'O cisto simples: 65 a 70% das doenças císticas. Não é hereditário.'),
  ('nefro-a2-f03', 'nefro-a2', 3, 'Como é o cisto simples?', 'Esférico, de limites precisos, unilocular, com parede fina e lisa. Costuma medir de 0,5 a 1 cm.'),
  ('nefro-a2-f04', 'nefro-a2', 4, 'Qual é a conduta no cisto simples?', 'Observar: uma reavaliação com exame de imagem por ano.'),
  ('nefro-a2-f05', 'nefro-a2', 5, 'Bosniak I e II: qual a conduta?', 'Acompanhar na atenção básica, com ecografia uma vez por ano. Não precisa encaminhar.'),
  ('nefro-a2-f06', 'nefro-a2', 6, 'A partir de qual categoria de Bosniak o encaminhamento é obrigatório?', 'IIF (a “2F”): encaminhar ao nefrologista ou urologista, com tomografia e acompanhamento por 5 anos.'),
  ('nefro-a2-f07', 'nefro-a2', 7, 'O que é o Bosniak IV?', 'Cisto considerado câncer em 85 a 100% dos casos. A conduta é cirurgia direto.'),
  ('nefro-a2-f08', 'nefro-a2', 8, 'Onde ficam os cistos na doença policística autossômica recessiva?', 'Essencialmente nos ductos coletores.'),
  ('nefro-a2-f09', 'nefro-a2', 9, 'Qual a chance de outro filho com doença policística recessiva?', '1 em 4 (25% a cada gestação), quando os dois pais carregam o gene.'),
  ('nefro-a2-f10', 'nefro-a2', 10, 'Quais os achados da policística recessiva no recém-nascido?', 'Oligoidrâmnio, falha dos ductos coletores e dilatação cística das vias biliares. Cerca de 60% evoluem para doença renal crônica até o quarto mês.'),
  ('nefro-a2-f11', 'nefro-a2', 11, 'Policística dominante: frequência e quando os cistos aparecem?', '1 em 400 a 1.000 nascimentos. Os cistos crescem entre os 30 e os 40 anos, mas existem desde a vida intrauterina.'),
  ('nefro-a2-f12', 'nefro-a2', 12, 'Qual gene é mais alterado na policística dominante?', 'PKD1, que produz a policistina 1: 85% dos casos, no braço curto do cromossomo 16.'),
  ('nefro-a2-f13', 'nefro-a2', 13, 'Por que a policística dominante é uma doença sistêmica?', 'A policistina existe também no fígado, pâncreas, ovários, testículos, valvas do coração, olho, intestino e cérebro.'),
  ('nefro-a2-f14', 'nefro-a2', 14, 'Qual é o primeiro sintoma da policística dominante?', 'Dor lombar, pela distensão da cápsula do rim (cápsula de Gerota) pelos cistos.'),
  ('nefro-a2-f15', 'nefro-a2', 15, 'Por que investigar aneurisma cerebral no paciente policístico?', 'A doença se associa a aneurismas, com risco de acidente vascular cerebral hemorrágico. A diretriz KDIGO de 2025 manda investigar.'),
  ('nefro-a2-f16', 'nefro-a2', 16, 'Qual é o mecanismo da hipertensão na policística dominante?', 'Os cistos comprimem a mácula densa e ativam o sistema renina-angiotensina-aldosterona. Aparece cedo, em mais de 50%.'),
  ('nefro-a2-f17', 'nefro-a2', 17, 'O que faz a policística dominante piorar mais rápido?', 'Alteração no gene PKD1, sexo masculino e já ser hipertenso quando descobriu a doença.'),
  ('nefro-a2-f18', 'nefro-a2', 18, 'Quantos cistos sugerem policística dominante, conforme a idade?', '15 a 29 anos: 2 ou mais no total. 30 a 59 anos: 2 ou mais em cada rim. 60 anos ou mais: 4 ou mais em cada rim.'),
  ('nefro-a2-f19', 'nefro-a2', 19, 'O que orientar ao policístico enquanto espera o especialista?', 'Mais de 3 L de água por dia, no máximo 200 mL de café ou cafeína e evitar impacto repetitivo (microtraumas).'),
  ('nefro-a2-f20', 'nefro-a2', 20, 'Como tratar a hematúria do policístico?', 'Repouso por 24 a 48 horas. Se não melhorar, o urologista faz uma pequena descompressão do cisto.'),
  ('nefro-a2-f21', 'nefro-a2', 21, 'Qual antibiótico para o cisto infectado?', 'Um lipossolúvel: quinolona, cloranfenicol ou sulfametoxazol com trimetoprima.'),
  ('nefro-a2-f22', 'nefro-a2', 22, 'Como age a tolvaptana?', 'Bloqueia o receptor V2 do hormônio antidiurético: o paciente urina mais, os túbulos ficam abertos e formam-se menos cistos. Ainda não está no Brasil.'),
  ('nefro-a2-f23', 'nefro-a2', 23, 'O que é o rim em esponja medular e como tratar?', 'Dilatação cística dos coletores da medula, em menos de 1% da população. Facilita cálculos: alcalinizar a urina.'),
  ('nefro-a2-f24', 'nefro-a2', 24, 'Doença cística adquirida: em quem aparece e qual o risco?', 'Em quem faz diálise há muitos anos. Os cistos têm maior risco de virar câncer: fazer exame de imagem.'),
  ('nefro-a2-f25', 'nefro-a2', 25, 'Do que é feito o angiomiolipoma?', 'Gordura, músculo liso e vasos sanguíneos (hamartoma). Geralmente é achado de exame.'),
  ('nefro-a2-f26', 'nefro-a2', 26, 'Quando o angiomiolipoma preocupa?', 'Se é pobre em gordura, cresce mais de 2,5 mm por ano, passa de 6 cm ou sangra.');
